/* Авто-сгенерированный словарь переводов (help). Ключ — нормализованная русская строка; значения — en, fr, de, es, it, zh. */
window.__I18N_SITE=Object.assign(window.__I18N_SITE||{},{"HarmonyAi — Помощь":{"en":"HarmonyAi — Help","fr":"HarmonyAi — Aide","de":"HarmonyAi — Hilfe","es":"HarmonyAi — Ayuda","it":"HarmonyAi — Guida","zh":"HarmonyAi — 帮助"},"Русский":{"en":"Russian","fr":"Russe","de":"Russisch","es":"Ruso","it":"Russo","zh":"俄语"},"Сайт":{"en":"Site","fr":"Site","de":"Seite","es":"Sitio","it":"Sito","zh":"网站"},"Частые вопросы о сайте HarmonyAi":{"en":"Frequently asked questions about HarmonyAi","fr":"Questions fréquentes sur HarmonyAi","de":"Häufige Fragen zu HarmonyAi","es":"Preguntas frecuentes sobre HarmonyAi","it":"Domande frequenti su HarmonyAi","zh":"HarmonyAi 常见问题"},"Что такое HarmonyAI?":{"en":"What is HarmonyAI?","fr":"Qu’est-ce que HarmonyAI ?","de":"Was ist HarmonyAI?","es":"¿Qué es HarmonyAI?","it":"Che cos’è HarmonyAI?","zh":"HarmonyAI 是什么？"},"HarmonyAI - это искусственный интеллект, разработанный специально для учеников музыкальных школ. В отличие от обычных универсальных помощников, он обучен не только на общедоступных данных, но и на нескольких сотнях учебников, методических пособий и практических заданий по сольфеджио, музыкальной грамоте, теории музыки, гармонии и музыкальной литературе. Благодаря этому сервис лучше понимает музыкальные термины, умеет объяснять темы простым языком и помогает готовиться к урокам, контрольным работам, экзаменам и вступительным испытаниям. При этом HarmonyAI сохраняет все привычные возможности современного искусственного интеллекта: отвечает на вопросы, пишет тексты, анализирует информацию, помогает с учебой и выполняет множество других задач.":{"en":"HarmonyAI is an artificial intelligence designed specifically for music school students. Unlike ordinary universal assistants, it has been trained not only on publicly available data but also on several hundred textbooks, teaching guides and practical exercises in solfège, music fundamentals, music theory, harmony and music literature. As a result, it understands musical terms better, can explain topics in simple language and helps you prepare for lessons, tests, exams and entrance auditions. At the same time, HarmonyAI keeps all the familiar abilities of modern AI: it answers questions, writes texts, analyses information, helps with studying and does many other tasks.","fr":"HarmonyAI est une intelligence artificielle conçue spécialement pour les élèves d’écoles de musique. Contrairement aux assistants universels habituels, elle a été entraînée non seulement sur des données publiques, mais aussi sur plusieurs centaines de manuels, guides pédagogiques et exercices pratiques de solfège, de formation musicale, de théorie de la musique, d’harmonie et de littérature musicale. Elle comprend donc mieux les termes musicaux, sait expliquer les sujets simplement et aide à préparer les cours, les contrôles, les examens et les concours d’entrée. HarmonyAI conserve en même temps toutes les capacités habituelles d’une IA moderne : répondre aux questions, rédiger des textes, analyser des informations, aider dans les études et bien d’autres tâches.","de":"HarmonyAI ist eine künstliche Intelligenz, die speziell für Schülerinnen und Schüler von Musikschulen entwickelt wurde. Anders als gewöhnliche Universalassistenten wurde sie nicht nur mit öffentlich zugänglichen Daten trainiert, sondern auch mit mehreren Hundert Lehrbüchern, methodischen Handreichungen und praktischen Aufgaben zu Solfège, allgemeiner Musiklehre, Musiktheorie, Harmonielehre und Musikliteratur. Dadurch versteht der Dienst musikalische Fachbegriffe besser, erklärt Themen in einfacher Sprache und hilft bei der Vorbereitung auf Unterricht, Tests, Prüfungen und Aufnahmeprüfungen. Gleichzeitig behält HarmonyAI alle gewohnten Fähigkeiten moderner KI: Er beantwortet Fragen, schreibt Texte, analysiert Informationen, hilft beim Lernen und erledigt viele weitere Aufgaben.","es":"HarmonyAI es una inteligencia artificial creada específicamente para estudiantes de escuelas de música. A diferencia de los asistentes universales habituales, se ha entrenado no solo con datos públicos, sino también con varios cientos de manuales, guías didácticas y ejercicios prácticos de solfeo, lenguaje musical, teoría de la música, armonía y literatura musical. Gracias a ello entiende mejor los términos musicales, explica los temas con palabras sencillas y ayuda a preparar clases, controles, exámenes y pruebas de acceso. Al mismo tiempo, HarmonyAI conserva todas las capacidades habituales de la IA moderna: responde preguntas, escribe textos, analiza información, ayuda a estudiar y realiza muchas otras tareas.","it":"HarmonyAI è un’intelligenza artificiale pensata appositamente per gli studenti delle scuole di musica. A differenza dei comuni assistenti universali, è stata addestrata non solo su dati pubblici ma anche su diverse centinaia di manuali, guide didattiche ed esercizi pratici di solfeggio, teoria musicale di base, teoria della musica, armonia e storia della musica. Per questo capisce meglio i termini musicali, spiega gli argomenti in modo semplice e aiuta a prepararsi a lezioni, verifiche, esami e prove di ammissione. Allo stesso tempo HarmonyAI mantiene tutte le capacità abituali dell’IA moderna: risponde alle domande, scrive testi, analizza informazioni, aiuta nello studio e svolge molti altri compiti.","zh":"HarmonyAI 是专为音乐学校学生打造的人工智能。与普通的通用助手不同，它不仅使用公开数据进行训练，还学习了数百本视唱练耳、基本乐理、音乐理论、和声和音乐文献方面的教材、教学参考书和练习。因此，它更懂音乐术语，能用通俗的语言讲解知识点，帮助你准备课程、测验、考试和入学考核。同时，HarmonyAI 保留了现代人工智能的所有常用能力：回答问题、撰写文字、分析信息、辅助学习以及完成许多其他任务。"},"Чем HarmonyAI отличается от других искусственных интеллектов?":{"en":"How is HarmonyAI different from other AIs?","fr":"En quoi HarmonyAI diffère-t-elle des autres IA ?","de":"Worin unterscheidet sich HarmonyAI von anderen KIs?","es":"¿En qué se diferencia HarmonyAI de otras inteligencias artificiales?","it":"In cosa HarmonyAI è diversa dalle altre IA?","zh":"HarmonyAI 和其他人工智能有什么不同？"},"Большинство сервисов искусственного интеллекта являются универсальными помощниками и не имеют глубоких знаний в области музыкального образования. HarmonyAI был создан именно для учеников музыкальных школ. Он понимает программу обучения, музыкальные термины, особенности нотной записи и способен объяснять сложные темы значительно понятнее. Кроме того, сервис умеет распознавать музыкальные произведения, работать с нотными диктантами и постепенно получает новые специализированные функции, которых нет у большинства аналогов.":{"en":"Most AI services are universal assistants without deep knowledge of music education. HarmonyAI was built specifically for music school students. It understands the curriculum, musical terms and the specifics of notation, and can explain difficult topics much more clearly. The service can also recognise pieces of music, work with music dictations and keeps gaining new specialised features that most alternatives don’t have.","fr":"La plupart des services d’IA sont des assistants universels sans connaissance approfondie de l’enseignement musical. HarmonyAI a été créée précisément pour les élèves d’écoles de musique. Elle comprend le programme, les termes musicaux et les particularités de la notation, et sait expliquer les sujets difficiles bien plus clairement. Le service sait aussi reconnaître des œuvres, travailler avec des dictées musicales et reçoit progressivement de nouvelles fonctions spécialisées que la plupart des alternatives n’ont pas.","de":"Die meisten KI-Dienste sind Universalassistenten ohne tiefes Wissen über Musikausbildung. HarmonyAI wurde genau für Musikschülerinnen und -schüler geschaffen. Er versteht den Lehrplan, musikalische Begriffe und die Besonderheiten der Notenschrift und kann schwierige Themen deutlich verständlicher erklären. Außerdem erkennt der Dienst Musikstücke, arbeitet mit Musikdiktaten und erhält nach und nach neue Spezialfunktionen, die den meisten Alternativen fehlen.","es":"La mayoría de los servicios de IA son asistentes universales sin conocimientos profundos de educación musical. HarmonyAI se creó precisamente para estudiantes de escuelas de música. Entiende el plan de estudios, los términos musicales y las particularidades de la notación, y explica los temas difíciles con mucha más claridad. Además, reconoce obras musicales, trabaja con dictados musicales y va incorporando funciones especializadas que la mayoría de las alternativas no tienen.","it":"La maggior parte dei servizi di IA sono assistenti universali senza conoscenze approfondite dell’educazione musicale. HarmonyAI è stata creata proprio per gli studenti delle scuole di musica. Capisce il programma di studio, i termini musicali e le particolarità della notazione, e sa spiegare gli argomenti difficili in modo molto più chiaro. Inoltre riconosce i brani musicali, lavora con i dettati musicali e acquisisce gradualmente nuove funzioni specialistiche che la maggior parte delle alternative non ha.","zh":"大多数人工智能服务都是通用助手，缺乏音乐教育方面的深入知识。HarmonyAI 正是为音乐学校学生而打造的。它了解教学大纲、音乐术语和记谱特点，能把难懂的知识讲得清楚得多。此外，它还能识别音乐作品、处理听写练习，并不断加入大多数同类产品没有的专业功能。"},"Что умеет HarmonyAI?":{"en":"What can HarmonyAI do?","fr":"Que sait faire HarmonyAI ?","de":"Was kann HarmonyAI?","es":"¿Qué sabe hacer HarmonyAI?","it":"Cosa sa fare HarmonyAI?","zh":"HarmonyAI 能做什么？"},"HarmonyAI способен отвечать на вопросы практически по любой теме, объяснять учебный материал, помогать выполнять домашние задания, анализировать изображения, читать документы, создавать изображения по текстовому описанию, распознавать музыкальные произведения, анализировать нотные диктанты, помогать с музыкальной теорией, сольфеджио, гармонией и музыкальной литературой. Искусственный интеллект также умеет переводить тексты, помогать с программированием, искать ошибки и объяснять свои ответы простым языком.":{"en":"HarmonyAI can answer questions on almost any topic, explain study material, help with homework, analyse images, read documents, create images from a text description, recognise pieces of music, analyse music dictations and help with music theory, solfège, harmony and music literature. The AI can also translate texts, help with programming, find mistakes and explain its answers in simple language.","fr":"HarmonyAI sait répondre à des questions sur presque tous les sujets, expliquer la matière, aider aux devoirs, analyser des images, lire des documents, créer des images à partir d’une description, reconnaître des œuvres, analyser des dictées musicales et aider en théorie de la musique, solfège, harmonie et littérature musicale. L’IA sait aussi traduire des textes, aider à programmer, trouver des erreurs et expliquer ses réponses simplement.","de":"HarmonyAI beantwortet Fragen zu fast jedem Thema, erklärt Lernstoff, hilft bei Hausaufgaben, analysiert Bilder, liest Dokumente, erstellt Bilder aus einer Textbeschreibung, erkennt Musikstücke, analysiert Musikdiktate und hilft bei Musiktheorie, Solfège, Harmonielehre und Musikliteratur. Die KI kann außerdem Texte übersetzen, beim Programmieren helfen, Fehler finden und ihre Antworten verständlich erklären.","es":"HarmonyAI responde preguntas sobre casi cualquier tema, explica la materia, ayuda con los deberes, analiza imágenes, lee documentos, crea imágenes a partir de una descripción, reconoce obras musicales, analiza dictados musicales y ayuda con teoría de la música, solfeo, armonía y literatura musical. La IA también traduce textos, ayuda a programar, encuentra errores y explica sus respuestas con sencillez.","it":"HarmonyAI risponde a domande su quasi ogni argomento, spiega il materiale di studio, aiuta con i compiti, analizza immagini, legge documenti, crea immagini da una descrizione testuale, riconosce brani musicali, analizza dettati musicali e aiuta con teoria musicale, solfeggio, armonia e storia della musica. L’IA sa anche tradurre testi, aiutare a programmare, trovare errori e spiegare le sue risposte in modo semplice.","zh":"HarmonyAI 几乎能回答任何主题的问题：讲解课程内容、辅导作业、分析图片、阅读文档、根据文字描述生成图片、识别音乐作品、分析听写练习，并在音乐理论、视唱练耳、和声及音乐文献方面提供帮助。它还能翻译文本、协助编程、查找错误，并用浅显的语言解释自己的回答。"},"Может ли HarmonyAI читать файлы?":{"en":"Can HarmonyAI read files?","fr":"HarmonyAI peut-elle lire des fichiers ?","de":"Kann HarmonyAI Dateien lesen?","es":"¿Puede HarmonyAI leer archivos?","it":"HarmonyAI può leggere i file?","zh":"HarmonyAI 能读取文件吗？"},"Да. HarmonyAI поддерживает работу с различными документами и текстовыми файлами. После загрузки файла искусственный интеллект может проанализировать его содержимое, ответить на вопросы, сделать краткое содержание, объяснить сложные темы или помочь найти нужную информацию.":{"en":"Yes. HarmonyAI works with various documents and text files. After you upload a file, the AI can analyse its contents, answer questions, write a summary, explain difficult topics or help you find the information you need.","fr":"Oui. HarmonyAI prend en charge différents documents et fichiers texte. Après le téléversement, l’IA peut analyser le contenu, répondre aux questions, faire un résumé, expliquer des sujets difficiles ou aider à trouver l’information voulue.","de":"Ja. HarmonyAI arbeitet mit verschiedenen Dokumenten und Textdateien. Nach dem Hochladen kann die KI den Inhalt analysieren, Fragen beantworten, eine Zusammenfassung erstellen, schwierige Themen erklären oder beim Finden von Informationen helfen.","es":"Sí. HarmonyAI trabaja con diversos documentos y archivos de texto. Tras subir un archivo, la IA puede analizar su contenido, responder preguntas, hacer un resumen, explicar temas difíciles o ayudarte a encontrar la información que buscas.","it":"Sì. HarmonyAI supporta vari documenti e file di testo. Dopo il caricamento, l’IA può analizzarne il contenuto, rispondere alle domande, fare un riassunto, spiegare argomenti difficili o aiutarti a trovare le informazioni che cerchi.","zh":"可以。HarmonyAI 支持多种文档和文本文件。上传文件后，它可以分析内容、回答问题、生成摘要、讲解难点，或帮你查找所需信息。"},"Для кого предназначен HarmonyAI?":{"en":"Who is HarmonyAI for?","fr":"À qui s’adresse HarmonyAI ?","de":"Für wen ist HarmonyAI gedacht?","es":"¿Para quién es HarmonyAI?","it":"A chi è rivolta HarmonyAI?","zh":"HarmonyAI 适合谁使用？"},"HarmonyAI разработан в первую очередь для учеников музыкальных школ, однако пользоваться сервисом могут также преподаватели, родители и все, кто изучает музыку самостоятельно. Он подходит как начинающим музыкантам, так и учащимся старших классов, помогая быстрее понимать сложные темы и экономить время при подготовке к занятиям.":{"en":"HarmonyAI was designed primarily for music school students, but teachers, parents and anyone learning music on their own can use it too. It suits both beginner musicians and senior students, helping them grasp difficult topics faster and save time preparing for lessons.","fr":"HarmonyAI a été conçue avant tout pour les élèves d’écoles de musique, mais les professeurs, les parents et tous ceux qui apprennent la musique en autodidacte peuvent aussi l’utiliser. Elle convient aussi bien aux musiciens débutants qu’aux élèves plus avancés, en les aidant à comprendre plus vite les sujets difficiles et à gagner du temps dans leur préparation.","de":"HarmonyAI wurde vor allem für Musikschülerinnen und -schüler entwickelt, kann aber auch von Lehrkräften, Eltern und allen genutzt werden, die selbstständig Musik lernen. Der Dienst eignet sich für Einsteiger ebenso wie für Fortgeschrittene und hilft, schwierige Themen schneller zu verstehen und bei der Vorbereitung Zeit zu sparen.","es":"HarmonyAI se diseñó sobre todo para estudiantes de escuelas de música, pero también pueden usarlo profesores, padres y cualquiera que estudie música por su cuenta. Sirve tanto a músicos principiantes como a estudiantes de cursos superiores y les ayuda a entender antes los temas difíciles y a ahorrar tiempo al preparar las clases.","it":"HarmonyAI è stata pensata soprattutto per gli studenti delle scuole di musica, ma possono usarla anche insegnanti, genitori e chiunque studi musica da solo. È adatta sia ai musicisti alle prime armi sia agli studenti più avanzati, e li aiuta a capire più in fretta gli argomenti difficili e a risparmiare tempo nella preparazione.","zh":"HarmonyAI 主要面向音乐学校的学生，但教师、家长以及自学音乐的人也都可以使用。无论是初学者还是高年级学生，它都能帮助更快理解难点，节省备课和复习时间。"},"Можно ли пользоваться бесплатно?":{"en":"Can I use it for free?","fr":"Peut-on l’utiliser gratuitement ?","de":"Kann man es kostenlos nutzen?","es":"¿Se puede usar gratis?","it":"Si può usare gratis?","zh":"可以免费使用吗？"},"Да. HarmonyAI имеет полностью бесплатный тариф, позволяющий познакомиться с основными возможностями сервиса. Однако бесплатная версия имеет ежедневные лимиты и некоторые ограничения функций. Если лимитов недостаточно или требуется доступ ко всем возможностям платформы, можно оформить Pro-подписку и пользоваться сервисом без ограничений.":{"en":"Yes. HarmonyAI has a completely free plan that lets you get to know the main features. The free version does have usage limits and some feature restrictions. If the limits aren’t enough or you need access to everything the platform offers, you can get a Pro subscription and use the service without restrictions.","fr":"Oui. HarmonyAI propose une formule entièrement gratuite pour découvrir les principales fonctions. La version gratuite comporte toutefois des limites d’utilisation et certaines restrictions. Si les limites ne suffisent pas ou si vous voulez accéder à toutes les possibilités de la plateforme, vous pouvez souscrire à l’abonnement Pro et utiliser le service sans restriction.","de":"Ja. HarmonyAI hat einen völlig kostenlosen Tarif, mit dem Sie die wichtigsten Funktionen kennenlernen. Die kostenlose Version hat jedoch Nutzungslimits und einige Einschränkungen. Reichen die Limits nicht oder brauchen Sie alle Möglichkeiten der Plattform, können Sie das Pro-Abo abschließen und den Dienst ohne Einschränkungen nutzen.","es":"Sí. HarmonyAI tiene un plan totalmente gratuito para conocer las funciones principales. La versión gratuita tiene límites de uso y algunas restricciones. Si los límites no te bastan o necesitas todas las posibilidades de la plataforma, puedes contratar la suscripción Pro y usar el servicio sin restricciones.","it":"Sì. HarmonyAI ha un piano completamente gratuito che permette di conoscere le funzioni principali. La versione gratuita ha però limiti di utilizzo e alcune restrizioni. Se i limiti non bastano o ti servono tutte le possibilità della piattaforma, puoi attivare l’abbonamento Pro e usare il servizio senza restrizioni.","zh":"可以。HarmonyAI 提供完全免费的套餐，可体验主要功能。但免费版有使用额度和部分功能限制。如果额度不够用，或需要使用平台的全部功能，可以开通 Pro 订阅，不受限制地使用。"},"Нужна ли регистрация?":{"en":"Do I need to register?","fr":"Faut-il s’inscrire ?","de":"Ist eine Registrierung nötig?","es":"¿Hace falta registrarse?","it":"Serve la registrazione?","zh":"需要注册吗？"},"Да. Для использования HarmonyAI необходимо зарегистрироваться при помощи электронной почты. Вместо обычного пароля используется безопасный вход по одноразовому коду подтверждения, который приходит на электронную почту. Это упрощает авторизацию и снижает риск потери пароля.":{"en":"Yes. To use HarmonyAI you need to register with your email. Instead of a regular password, a secure sign-in with a one-time confirmation code sent to your email is used. This simplifies signing in and reduces the risk of losing a password.","fr":"Oui. Pour utiliser HarmonyAI, il faut s’inscrire avec une adresse e-mail. Au lieu d’un mot de passe classique, la connexion se fait de manière sécurisée avec un code de confirmation à usage unique envoyé par e-mail. Cela simplifie la connexion et réduit le risque de perdre un mot de passe.","de":"Ja. Um HarmonyAI zu nutzen, registrieren Sie sich mit Ihrer E-Mail-Adresse. Statt eines gewöhnlichen Passworts erfolgt die Anmeldung sicher mit einem Einmalcode, der per E-Mail kommt. Das vereinfacht die Anmeldung und senkt das Risiko, ein Passwort zu verlieren.","es":"Sí. Para usar HarmonyAI hay que registrarse con un correo electrónico. En lugar de una contraseña normal, se usa un acceso seguro con un código de confirmación de un solo uso que llega al correo. Así el acceso es más sencillo y se reduce el riesgo de perder la contraseña.","it":"Sì. Per usare HarmonyAI bisogna registrarsi con l’email. Al posto della solita password si usa un accesso sicuro con un codice di conferma monouso che arriva via email. Così l’accesso è più semplice e si riduce il rischio di perdere la password.","zh":"需要。使用 HarmonyAI 需用电子邮箱注册。登录时不使用普通密码，而是通过发送到邮箱的一次性验证码安全登录。这样登录更简单，也降低了密码丢失的风险。"},"Какие языки поддерживаются?":{"en":"Which languages are supported?","fr":"Quelles langues sont prises en charge ?","de":"Welche Sprachen werden unterstützt?","es":"¿Qué idiomas se admiten?","it":"Quali lingue sono supportate?","zh":"支持哪些语言？"},"HarmonyAI поддерживает семь языков интерфейса: русский, английский, немецкий, французский, испанский, итальянский и китайский. Язык определяется автоматически по вашему региону и переключается кнопкой выбора языка вверху страницы. Задавать вопросы ИИ можно на любом языке — он ответит на языке вопроса.":{"en":"HarmonyAI supports seven interface languages: Russian, English, German, French, Spanish, Italian and Chinese. The language is detected automatically from your region and can be switched with the language button at the top of the page. You can ask the AI questions in any language — it answers in the language of the question.","fr":"HarmonyAI prend en charge sept langues d’interface : russe, anglais, allemand, français, espagnol, italien et chinois. La langue est détectée automatiquement selon votre région et se change avec le bouton de langue en haut de la page. Vous pouvez poser vos questions à l’IA dans n’importe quelle langue — elle répond dans la langue de la question.","de":"HarmonyAI unterstützt sieben Sprachen der Oberfläche: Russisch, Englisch, Deutsch, Französisch, Spanisch, Italienisch und Chinesisch. Die Sprache wird automatisch anhand Ihrer Region erkannt und lässt sich über die Sprachauswahl oben auf der Seite ändern. Fragen an die KI können Sie in jeder Sprache stellen — sie antwortet in der Sprache der Frage.","es":"HarmonyAI admite siete idiomas de interfaz: ruso, inglés, alemán, francés, español, italiano y chino. El idioma se detecta automáticamente según tu región y se cambia con el botón de idioma en la parte superior de la página. Puedes preguntar a la IA en cualquier idioma: responderá en el idioma de la pregunta.","it":"HarmonyAI supporta sette lingue dell’interfaccia: russo, inglese, tedesco, francese, spagnolo, italiano e cinese. La lingua viene rilevata automaticamente in base alla tua regione e si cambia con il pulsante della lingua in alto nella pagina. Puoi fare domande all’IA in qualsiasi lingua — risponderà nella lingua della domanda.","zh":"HarmonyAI 支持七种界面语言：俄语、英语、德语、法语、西班牙语、意大利语和中文。系统会根据你所在地区自动选择语言，也可通过页面顶部的语言按钮切换。你可以用任何语言向 AI 提问——它会用提问的语言回答。"},"Какие модели использует HarmonyAI?":{"en":"Which models does HarmonyAI use?","fr":"Quels modèles HarmonyAI utilise-t-elle ?","de":"Welche Modelle nutzt HarmonyAI?","es":"¿Qué modelos usa HarmonyAI?","it":"Quali modelli usa HarmonyAI?","zh":"HarmonyAI 使用哪些模型？"},"Бесплатный тариф использует модель Adanatos. Она подходит для большинства повседневных задач, но некоторые функции сервиса недоступны. Подписка Pro открывает доступ к модели Dynatos — самой мощной модели HarmonyAI. Она обеспечивает более качественные ответы, лучшие рассуждения, улучшенную генерацию изображений, доступ к распознаванию музыки и всем новым возможностям сервиса сразу после их появления.":{"en":"The free plan uses the Adanatos model. It is suitable for most everyday tasks, but some features of the service are unavailable. The Pro subscription gives access to Dynatos, HarmonyAI’s most powerful model. It provides better answers, stronger reasoning, improved image generation, music recognition and all new features as soon as they appear.","fr":"La formule gratuite utilise le modèle Adanatos. Il convient à la plupart des tâches du quotidien, mais certaines fonctions du service ne sont pas disponibles. L’abonnement Pro donne accès à Dynatos, le modèle le plus puissant de HarmonyAI : des réponses de meilleure qualité, un meilleur raisonnement, une génération d’images améliorée, la reconnaissance musicale et toutes les nouveautés dès leur sortie.","de":"Der kostenlose Tarif nutzt das Modell Adanatos. Es eignet sich für die meisten Alltagsaufgaben, einige Funktionen des Dienstes sind aber nicht verfügbar. Das Pro-Abo öffnet den Zugang zu Dynatos, dem stärksten Modell von HarmonyAI: bessere Antworten, besseres Schlussfolgern, verbesserte Bilderzeugung, Musikerkennung und alle neuen Funktionen sofort nach ihrem Erscheinen.","es":"El plan gratuito usa el modelo Adanatos. Sirve para la mayoría de las tareas cotidianas, pero algunas funciones del servicio no están disponibles. La suscripción Pro da acceso a Dynatos, el modelo más potente de HarmonyAI: respuestas de mayor calidad, mejor razonamiento, generación de imágenes mejorada, reconocimiento musical y todas las novedades en cuanto aparecen.","it":"Il piano gratuito usa il modello Adanatos. È adatto alla maggior parte delle attività quotidiane, ma alcune funzioni del servizio non sono disponibili. L’abbonamento Pro dà accesso a Dynatos, il modello più potente di HarmonyAI: risposte di qualità superiore, ragionamento migliore, generazione di immagini migliorata, riconoscimento musicale e tutte le novità appena escono.","zh":"免费版使用 Adanatos 模型，可满足大多数日常需求，但部分功能不可用。Pro 订阅可使用 HarmonyAI 最强大的模型 Dynatos：回答质量更高、推理更强、图片生成效果更好，支持音乐识别，并第一时间获得所有新功能。"},"Может ли HarmonyAI искать информацию в интернете?":{"en":"Can HarmonyAI search the internet?","fr":"HarmonyAI peut-elle chercher sur Internet ?","de":"Kann HarmonyAI im Internet suchen?","es":"¿Puede HarmonyAI buscar en internet?","it":"HarmonyAI può cercare su Internet?","zh":"HarmonyAI 能联网搜索吗？"},"Да. При необходимости HarmonyAI может искать актуальную информацию в интернете и использовать ее при подготовке ответа. Это особенно полезно для поиска свежих новостей, изменений в законодательстве, расписаний, цен и другой информации, которая регулярно обновляется. Если поиск не требуется, искусственный интеллект отвечает на основе собственных знаний.":{"en":"Yes. When needed, HarmonyAI can look up current information on the internet and use it in its answer. This is especially useful for fresh news, changes in legislation, schedules, prices and other frequently updated information. If no search is needed, the AI answers from its own knowledge.","fr":"Oui. Si nécessaire, HarmonyAI peut chercher des informations à jour sur Internet et les utiliser dans sa réponse. C’est particulièrement utile pour l’actualité, les évolutions législatives, les horaires, les prix et toute information régulièrement mise à jour. Quand la recherche n’est pas utile, l’IA répond à partir de ses propres connaissances.","de":"Ja. Bei Bedarf sucht HarmonyAI aktuelle Informationen im Internet und nutzt sie für die Antwort. Das ist besonders hilfreich für Neuigkeiten, Gesetzesänderungen, Fahrpläne, Preise und andere sich regelmäßig ändernde Informationen. Ist keine Suche nötig, antwortet die KI aus eigenem Wissen.","es":"Sí. Cuando hace falta, HarmonyAI busca información actual en internet y la usa en la respuesta. Es especialmente útil para noticias recientes, cambios legislativos, horarios, precios y otra información que se actualiza a menudo. Si no hace falta buscar, la IA responde con sus propios conocimientos.","it":"Sì. Se necessario, HarmonyAI può cercare informazioni aggiornate su Internet e usarle nella risposta. È particolarmente utile per notizie recenti, modifiche normative, orari, prezzi e altre informazioni che cambiano spesso. Se la ricerca non serve, l’IA risponde in base alle proprie conoscenze.","zh":"可以。必要时，HarmonyAI 会联网搜索最新信息并用于回答，尤其适合查询最新新闻、法规变化、时间表、价格等经常更新的信息。如果不需要搜索，AI 会基于自身知识作答。"},"Может ли HarmonyAI анализировать документы?":{"en":"Can HarmonyAI analyse documents?","fr":"HarmonyAI peut-elle analyser des documents ?","de":"Kann HarmonyAI Dokumente analysieren?","es":"¿Puede HarmonyAI analizar documentos?","it":"HarmonyAI può analizzare documenti?","zh":"HarmonyAI 能分析文档吗？"},"Да. HarmonyAI умеет работать с документами различных форматов. Вы можете загрузить файл, после чего искусственный интеллект сможет прочитать его содержимое, объяснить непонятные моменты, сделать краткое содержание, ответить на вопросы по тексту или помочь найти нужную информацию.":{"en":"Yes. HarmonyAI works with documents in various formats. You can upload a file, and the AI will read its contents, explain unclear points, write a summary, answer questions about the text or help you find the information you need.","fr":"Oui. HarmonyAI sait travailler avec des documents de différents formats. Téléversez un fichier : l’IA pourra lire son contenu, expliquer les passages obscurs, faire un résumé, répondre à des questions sur le texte ou aider à trouver l’information utile.","de":"Ja. HarmonyAI arbeitet mit Dokumenten in verschiedenen Formaten. Laden Sie eine Datei hoch — die KI liest den Inhalt, erklärt unklare Stellen, fasst zusammen, beantwortet Fragen zum Text oder hilft beim Finden von Informationen.","es":"Sí. HarmonyAI trabaja con documentos de distintos formatos. Sube un archivo y la IA podrá leer su contenido, aclarar lo que no entiendas, hacer un resumen, responder preguntas sobre el texto o ayudarte a encontrar la información que necesitas.","it":"Sì. HarmonyAI lavora con documenti di vari formati. Carica un file e l’IA potrà leggerne il contenuto, spiegare i punti poco chiari, farne un riassunto, rispondere a domande sul testo o aiutarti a trovare le informazioni che servono.","zh":"可以。HarmonyAI 支持多种格式的文档。上传文件后，AI 可以阅读内容、解释难懂之处、生成摘要、回答与文本相关的问题，或帮你查找所需信息。"},"Может ли HarmonyAI генерировать изображения?":{"en":"Can HarmonyAI generate images?","fr":"HarmonyAI peut-elle générer des images ?","de":"Kann HarmonyAI Bilder erzeugen?","es":"¿Puede HarmonyAI generar imágenes?","it":"HarmonyAI può generare immagini?","zh":"HarmonyAI 能生成图片吗？"},"Да. HarmonyAI умеет создавать изображения по текстовому описанию. Вы можете подробно описать желаемый результат, а искусственный интеллект сгенерирует изображение на основе вашего запроса. Чем подробнее описание, тем точнее обычно получается результат.":{"en":"Yes. HarmonyAI can create images from a text description. Describe the desired result in detail and the AI will generate an image based on your request. The more detailed the description, the more accurate the result usually is.","fr":"Oui. HarmonyAI sait créer des images à partir d’une description. Décrivez en détail le résultat souhaité et l’IA générera une image d’après votre demande. Plus la description est précise, plus le résultat est généralement fidèle.","de":"Ja. HarmonyAI erstellt Bilder nach einer Textbeschreibung. Beschreiben Sie das gewünschte Ergebnis ausführlich, und die KI erzeugt ein Bild nach Ihrer Anfrage. Je genauer die Beschreibung, desto genauer meist das Ergebnis.","es":"Sí. HarmonyAI crea imágenes a partir de una descripción de texto. Describe con detalle lo que quieres y la IA generará una imagen según tu petición. Cuanto más detallada sea la descripción, más preciso suele ser el resultado.","it":"Sì. HarmonyAI crea immagini a partire da una descrizione testuale. Descrivi nel dettaglio il risultato che vuoi e l’IA genererà un’immagine in base alla richiesta. Più la descrizione è dettagliata, più il risultato di solito è preciso.","zh":"可以。HarmonyAI 能根据文字描述生成图片。详细描述你想要的效果，AI 就会据此生成图片。描述越详细，结果通常越准确。"},"Может ли HarmonyAI распознавать изображения?":{"en":"Can HarmonyAI recognise images?","fr":"HarmonyAI peut-elle reconnaître des images ?","de":"Kann HarmonyAI Bilder erkennen?","es":"¿Puede HarmonyAI reconocer imágenes?","it":"HarmonyAI può riconoscere le immagini?","zh":"HarmonyAI 能识别图片吗？"},"Да. HarmonyAI способен анализировать загруженные изображения. Он может описывать содержимое фотографии, распознавать объекты, читать текст, помогать с решением заданий по изображениям и отвечать на вопросы по содержимому картинки.":{"en":"Yes. HarmonyAI can analyse uploaded images. It can describe what is in a photo, recognise objects, read text, help solve tasks from images and answer questions about the picture’s contents.","fr":"Oui. HarmonyAI sait analyser les images téléversées. Elle peut décrire le contenu d’une photo, reconnaître des objets, lire du texte, aider à résoudre des exercices à partir d’images et répondre à des questions sur leur contenu.","de":"Ja. HarmonyAI analysiert hochgeladene Bilder. Er kann den Inhalt eines Fotos beschreiben, Objekte erkennen, Text lesen, bei Aufgaben auf Bildern helfen und Fragen zum Bildinhalt beantworten.","es":"Sí. HarmonyAI analiza las imágenes que subes. Puede describir lo que hay en una foto, reconocer objetos, leer texto, ayudar con ejercicios a partir de imágenes y responder preguntas sobre su contenido.","it":"Sì. HarmonyAI può analizzare le immagini caricate. Può descrivere il contenuto di una foto, riconoscere oggetti, leggere testo, aiutare a risolvere esercizi da immagini e rispondere a domande sul loro contenuto.","zh":"可以。HarmonyAI 能分析上传的图片：描述照片内容、识别物体、读取文字、帮助解答图片中的题目，并回答与图片内容相关的问题。"},"Как работает распознавание музыки?":{"en":"How does music recognition work?","fr":"Comment fonctionne la reconnaissance musicale ?","de":"Wie funktioniert die Musikerkennung?","es":"¿Cómo funciona el reconocimiento musical?","it":"Come funziona il riconoscimento musicale?","zh":"音乐识别是如何工作的？"},"Пользователь загружает аудиофайл, после чего HarmonyAI анализирует его содержимое. Если это музыкальное произведение, искусственный интеллект определяет его название, композитора, исполнителя и предоставляет дополнительную информацию о произведении. Если загружен нотный диктант, HarmonyAI распознает услышанные ноты и старается построить нотную запись, максимально соответствующую оригиналу.":{"en":"You upload an audio file and HarmonyAI analyses its contents. If it is a piece of music, the AI identifies its title, composer and performer and provides additional information about it. If it is a music dictation, HarmonyAI recognises the notes it hears and tries to build notation that matches the original as closely as possible.","fr":"L’utilisateur téléverse un fichier audio, puis HarmonyAI en analyse le contenu. S’il s’agit d’une œuvre musicale, l’IA en détermine le titre, le compositeur, l’interprète et fournit des informations complémentaires. S’il s’agit d’une dictée musicale, HarmonyAI reconnaît les notes entendues et s’efforce d’en établir une notation aussi fidèle que possible à l’original.","de":"Sie laden eine Audiodatei hoch, und HarmonyAI analysiert den Inhalt. Handelt es sich um ein Musikstück, ermittelt die KI Titel, Komponist und Interpret und liefert weitere Informationen dazu. Bei einem Musikdiktat erkennt HarmonyAI die gehörten Töne und versucht, eine möglichst originalgetreue Notenschrift zu erstellen.","es":"Subes un archivo de audio y HarmonyAI analiza su contenido. Si es una obra musical, la IA identifica el título, el compositor y el intérprete y ofrece información adicional sobre ella. Si es un dictado musical, HarmonyAI reconoce las notas que oye e intenta construir una partitura lo más fiel posible al original.","it":"Carichi un file audio e HarmonyAI ne analizza il contenuto. Se è un brano musicale, l’IA ne individua titolo, compositore ed esecutore e fornisce informazioni aggiuntive. Se è un dettato musicale, HarmonyAI riconosce le note che sente e cerca di costruire una notazione il più possibile fedele all’originale.","zh":"用户上传音频文件后，HarmonyAI 会分析其内容。如果是一首音乐作品，AI 会识别曲名、作曲家和演奏者，并提供更多相关信息；如果是听写练习，HarmonyAI 会识别听到的音符，并尽量写出与原曲一致的乐谱。"},"Какие форматы аудио поддерживаются?":{"en":"Which audio formats are supported?","fr":"Quels formats audio sont pris en charge ?","de":"Welche Audioformate werden unterstützt?","es":"¿Qué formatos de audio se admiten?","it":"Quali formati audio sono supportati?","zh":"支持哪些音频格式？"},"HarmonyAI поддерживает большинство популярных аудиоформатов, используемых на современных устройствах. Вы можете загрузить запись, сделанную на телефон, диктофон, компьютер или скачанную из другого источника. Если файл воспроизводится на вашем устройстве и имеет распространенный формат, скорее всего сервис сможет его обработать. Для достижения максимально точного результата рекомендуется использовать запись без сильных шумов, помех и посторонних звуков.":{"en":"HarmonyAI supports most popular audio formats used on modern devices. You can upload a recording made on a phone, voice recorder or computer, or one downloaded from elsewhere. If the file plays on your device and is in a common format, the service can most likely process it. For the most accurate result, use a recording without strong noise, interference or extraneous sounds.","fr":"HarmonyAI prend en charge la plupart des formats audio courants des appareils modernes. Vous pouvez téléverser un enregistrement réalisé avec un téléphone, un dictaphone, un ordinateur ou téléchargé ailleurs. Si le fichier se lit sur votre appareil et utilise un format répandu, le service pourra très probablement le traiter. Pour un résultat optimal, utilisez un enregistrement sans bruit fort, parasites ni sons étrangers.","de":"HarmonyAI unterstützt die meisten gängigen Audioformate moderner Geräte. Sie können eine Aufnahme vom Handy, Diktiergerät oder Computer hochladen oder eine heruntergeladene Datei verwenden. Lässt sich die Datei auf Ihrem Gerät abspielen und hat sie ein verbreitetes Format, kann der Dienst sie sehr wahrscheinlich verarbeiten. Für ein möglichst genaues Ergebnis empfiehlt sich eine Aufnahme ohne starkes Rauschen, Störungen und Nebengeräusche.","es":"HarmonyAI admite la mayoría de los formatos de audio habituales de los dispositivos actuales. Puedes subir una grabación hecha con el móvil, una grabadora o el ordenador, o descargada de otro sitio. Si el archivo se reproduce en tu dispositivo y tiene un formato común, lo más probable es que el servicio pueda procesarlo. Para obtener el resultado más preciso, usa una grabación sin ruido fuerte, interferencias ni sonidos ajenos.","it":"HarmonyAI supporta la maggior parte dei formati audio diffusi sui dispositivi moderni. Puoi caricare una registrazione fatta con il telefono, un registratore o il computer, oppure scaricata altrove. Se il file si riproduce sul tuo dispositivo e ha un formato comune, molto probabilmente il servizio potrà elaborarlo. Per il risultato più preciso, usa una registrazione senza forti rumori, interferenze o suoni estranei.","zh":"HarmonyAI 支持现代设备上大多数常见音频格式。你可以上传用手机、录音笔或电脑录制的音频，也可以上传从其他地方下载的文件。只要文件能在你的设备上播放且格式常见，服务很可能就能处理。为获得最准确的结果，建议使用没有明显噪音、干扰和杂音的录音。"},"Какой максимальной длины может быть запись?":{"en":"What is the maximum length of a recording?","fr":"Quelle est la durée maximale d’un enregistrement ?","de":"Wie lang darf eine Aufnahme höchstens sein?","es":"¿Cuánto puede durar como máximo una grabación?","it":"Qual è la durata massima di una registrazione?","zh":"录音最长可以多长？"},"Максимальная продолжительность одного аудиофайла составляет 5 минут. Такое ограничение позволяет сохранить высокую скорость обработки и качество анализа. В большинстве случаев этого времени достаточно для распознавания музыкального произведения или анализа нотного диктанта. В будущем максимальная длительность может быть увеличена.":{"en":"The maximum length of one audio file is 5 minutes. This limit keeps processing fast and analysis accurate. In most cases this is enough to recognise a piece of music or analyse a music dictation. The maximum length may be increased in the future.","fr":"La durée maximale d’un fichier audio est de 5 minutes. Cette limite permet de garder un traitement rapide et une analyse de qualité. Dans la plupart des cas, c’est suffisant pour reconnaître une œuvre ou analyser une dictée musicale. Cette durée pourra être augmentée à l’avenir.","de":"Eine Audiodatei darf höchstens 5 Minuten lang sein. Diese Grenze sorgt für schnelle Verarbeitung und gute Analysequalität. Meist reicht das, um ein Musikstück zu erkennen oder ein Musikdiktat zu analysieren. Künftig kann die maximale Länge erhöht werden.","es":"La duración máxima de un archivo de audio es de 5 minutos. Este límite mantiene un procesamiento rápido y un análisis de calidad. En la mayoría de los casos basta para reconocer una obra o analizar un dictado musical. En el futuro la duración máxima podría ampliarse.","it":"La durata massima di un file audio è di 5 minuti. Questo limite mantiene l’elaborazione veloce e l’analisi accurata. Nella maggior parte dei casi basta per riconoscere un brano o analizzare un dettato musicale. In futuro la durata massima potrebbe aumentare.","zh":"单个音频文件最长 5 分钟。这一限制可确保处理速度和分析质量。大多数情况下，这个时长足以识别一首乐曲或分析一段听写。将来最长时长可能会增加。"},"Может ли HarmonyAI распознавать классическую музыку?":{"en":"Can HarmonyAI recognise classical music?","fr":"HarmonyAI peut-elle reconnaître la musique classique ?","de":"Kann HarmonyAI klassische Musik erkennen?","es":"¿Puede HarmonyAI reconocer música clásica?","it":"HarmonyAI può riconoscere la musica classica?","zh":"HarmonyAI 能识别古典音乐吗？"},"Да. HarmonyAI способен распознавать классические произведения различных эпох и композиторов. В отличие от обычных сервисов распознавания музыки, он старается не только определить название произведения, но и предоставить дополнительную информацию об авторе, истории создания и особенностях произведения. Следует учитывать, что это не специализированный сервис вроде Shazam, поэтому иногда точность определения может быть ниже, особенно при плохом качестве записи.":{"en":"Yes. HarmonyAI can recognise classical works from different eras and composers. Unlike ordinary music recognition services, it tries not only to identify the title but also to provide extra information about the composer, the history of the piece and its features. Keep in mind it isn’t a specialised service like Shazam, so recognition can sometimes be less accurate, especially with poor-quality recordings.","fr":"Oui. HarmonyAI sait reconnaître des œuvres classiques de différentes époques et de différents compositeurs. Contrairement aux services de reconnaissance habituels, elle essaie non seulement de trouver le titre, mais aussi de donner des informations sur l’auteur, l’histoire de l’œuvre et ses particularités. Ce n’est toutefois pas un service spécialisé comme Shazam : la précision peut parfois être moindre, surtout avec un enregistrement de mauvaise qualité.","de":"Ja. HarmonyAI erkennt klassische Werke verschiedener Epochen und Komponisten. Anders als gewöhnliche Musikerkennungsdienste versucht er nicht nur den Titel zu ermitteln, sondern liefert auch Informationen über den Komponisten, die Entstehungsgeschichte und Besonderheiten des Werks. Bedenken Sie, dass es kein spezialisierter Dienst wie Shazam ist; die Erkennung kann daher manchmal ungenauer sein, besonders bei schlechter Aufnahmequalität.","es":"Sí. HarmonyAI reconoce obras clásicas de distintas épocas y compositores. A diferencia de los servicios habituales de reconocimiento musical, no solo intenta identificar el título, sino que también aporta información sobre el autor, la historia y las particularidades de la obra. Ten en cuenta que no es un servicio especializado como Shazam, así que a veces la precisión puede ser menor, sobre todo con grabaciones de mala calidad.","it":"Sì. HarmonyAI riconosce opere classiche di epoche e compositori diversi. A differenza dei comuni servizi di riconoscimento musicale, non si limita a individuare il titolo, ma fornisce anche informazioni sull’autore, sulla storia e sulle caratteristiche dell’opera. Tieni presente che non è un servizio specializzato come Shazam, quindi a volte la precisione può essere inferiore, soprattutto con registrazioni di scarsa qualità.","zh":"可以。HarmonyAI 能识别不同时期、不同作曲家的古典作品。与普通音乐识别服务不同，它不仅会给出曲名，还会提供作者、创作背景和作品特点等信息。需要注意的是，它并非 Shazam 那样的专业识别服务，有时准确率可能较低，尤其是录音质量较差时。"},"Может ли HarmonyAI определить автора и исполнителя?":{"en":"Can HarmonyAI identify the composer and performer?","fr":"HarmonyAI peut-elle identifier le compositeur et l’interprète ?","de":"Kann HarmonyAI Komponist und Interpret bestimmen?","es":"¿Puede HarmonyAI identificar al autor y al intérprete?","it":"HarmonyAI può individuare autore ed esecutore?","zh":"HarmonyAI 能识别作曲家和演奏者吗？"},"Да. Если музыкальное произведение успешно распознано, искусственный интеллект по возможности укажет композитора, название произведения, исполнителя, а также другую доступную информацию. Объем информации зависит от конкретной записи и доступных данных.":{"en":"Yes. If a piece of music is recognised successfully, the AI will, where possible, name the composer, the title, the performer and other available information. How much information you get depends on the recording and the data available.","fr":"Oui. Si l’œuvre est reconnue, l’IA indiquera dans la mesure du possible le compositeur, le titre, l’interprète et d’autres informations disponibles. Leur quantité dépend de l’enregistrement et des données existantes.","de":"Ja. Wird ein Musikstück erkannt, nennt die KI nach Möglichkeit Komponist, Titel, Interpret und weitere verfügbare Informationen. Der Umfang hängt von der Aufnahme und den verfügbaren Daten ab.","es":"Sí. Si la obra se reconoce correctamente, la IA indicará, en la medida de lo posible, el compositor, el título, el intérprete y otra información disponible. La cantidad de datos depende de la grabación y de la información existente.","it":"Sì. Se il brano viene riconosciuto, l’IA indicherà, per quanto possibile, compositore, titolo, esecutore e altre informazioni disponibili. La quantità di informazioni dipende dalla registrazione e dai dati disponibili.","zh":"可以。若成功识别乐曲，AI 会尽可能给出作曲家、曲名、演奏者及其他可用信息。信息多少取决于具体录音和可用数据。"},"Насколько точны результаты распознавания?":{"en":"How accurate are the recognition results?","fr":"Quelle est la précision de la reconnaissance ?","de":"Wie genau sind die Erkennungsergebnisse?","es":"¿Qué precisión tiene el reconocimiento?","it":"Quanto sono precisi i risultati del riconoscimento?","zh":"识别结果有多准确？"},"Точность напрямую зависит от качества загруженного аудио. Если запись чистая, без сильных шумов и искажений, а произведение является достаточно известным, вероятность правильного определения очень высокая. При редких произведениях, концертных записях или плохом качестве звука возможны неточности. Именно поэтому рекомендуется использовать максимально качественные записи.":{"en":"Accuracy depends directly on the quality of the uploaded audio. If the recording is clean, without strong noise or distortion, and the piece is fairly well known, the chance of correct identification is very high. Rare works, live recordings or poor sound may lead to inaccuracies. That’s why it’s best to use the highest-quality recordings possible.","fr":"La précision dépend directement de la qualité de l’audio. Si l’enregistrement est propre, sans bruit ni distorsion importants, et que l’œuvre est assez connue, les chances d’une identification correcte sont très élevées. Pour des œuvres rares, des enregistrements en concert ou un son de mauvaise qualité, des erreurs sont possibles. C’est pourquoi il est conseillé d’utiliser des enregistrements de la meilleure qualité possible.","de":"Die Genauigkeit hängt direkt von der Qualität der hochgeladenen Aufnahme ab. Ist sie sauber, ohne starkes Rauschen und Verzerrungen, und das Stück recht bekannt, ist die Wahrscheinlichkeit einer richtigen Erkennung sehr hoch. Bei seltenen Werken, Konzertmitschnitten oder schlechtem Klang sind Ungenauigkeiten möglich. Deshalb empfiehlt sich eine möglichst hochwertige Aufnahme.","es":"La precisión depende directamente de la calidad del audio. Si la grabación es limpia, sin ruido ni distorsión fuertes, y la obra es bastante conocida, la probabilidad de acierto es muy alta. Con obras poco conocidas, grabaciones en directo o mala calidad de sonido puede haber imprecisiones. Por eso se recomienda usar grabaciones de la mejor calidad posible.","it":"La precisione dipende direttamente dalla qualità dell’audio caricato. Se la registrazione è pulita, senza forti rumori o distorsioni, e il brano è abbastanza noto, la probabilità di un riconoscimento corretto è molto alta. Con opere rare, registrazioni dal vivo o audio di scarsa qualità possono esserci imprecisioni. Per questo è consigliabile usare registrazioni della migliore qualità possibile.","zh":"准确率直接取决于上传音频的质量。如果录音干净、没有明显噪音和失真，且作品较为知名，正确识别的概率非常高。冷门作品、现场录音或音质较差时可能出现偏差。因此，建议尽量使用高质量的录音。"},"Может ли HarmonyAI определить аккорды?":{"en":"Can HarmonyAI identify chords?","fr":"HarmonyAI peut-elle reconnaître les accords ?","de":"Kann HarmonyAI Akkorde erkennen?","es":"¿Puede HarmonyAI identificar acordes?","it":"HarmonyAI può riconoscere gli accordi?","zh":"HarmonyAI 能识别和弦吗？"},"Да. HarmonyAI способен анализировать музыкальный материал и определять аккорды во многих случаях. Однако сложные джазовые гармонии, нестандартные аранжировки или записи с большим количеством инструментов могут снижать точность анализа. По мере развития проекта качество определения будет улучшаться.":{"en":"Yes. HarmonyAI can analyse musical material and identify chords in many cases. However, complex jazz harmonies, unusual arrangements or recordings with many instruments can reduce accuracy. Chord detection will improve as the project develops.","fr":"Oui. HarmonyAI sait analyser le matériau musical et identifier les accords dans de nombreux cas. Toutefois, les harmonies jazz complexes, les arrangements inhabituels ou les enregistrements avec beaucoup d’instruments peuvent réduire la précision. La qualité de la détection s’améliorera au fil du projet.","de":"Ja. HarmonyAI analysiert musikalisches Material und erkennt in vielen Fällen Akkorde. Komplexe Jazzharmonien, ungewöhnliche Arrangements oder Aufnahmen mit vielen Instrumenten können die Genauigkeit jedoch verringern. Mit der Weiterentwicklung des Projekts wird die Erkennung besser.","es":"Sí. HarmonyAI analiza el material musical e identifica los acordes en muchos casos. Sin embargo, las armonías complejas de jazz, los arreglos poco habituales o las grabaciones con muchos instrumentos pueden reducir la precisión. La calidad irá mejorando a medida que avance el proyecto.","it":"Sì. HarmonyAI analizza il materiale musicale e in molti casi individua gli accordi. Tuttavia armonie jazz complesse, arrangiamenti insoliti o registrazioni con molti strumenti possono ridurre la precisione. Con lo sviluppo del progetto il riconoscimento migliorerà.","zh":"可以。HarmonyAI 能分析音乐素材，并在多数情况下识别和弦。不过，复杂的爵士和声、非常规编配或乐器众多的录音可能降低准确度。随着项目发展，识别质量会不断提升。"},"Может ли HarmonyAI преобразовать музыку в полноценные ноты?":{"en":"Can HarmonyAI turn music into full sheet music?","fr":"HarmonyAI peut-elle transformer de la musique en partition complète ?","de":"Kann HarmonyAI Musik in vollständige Noten umwandeln?","es":"¿Puede HarmonyAI convertir música en una partitura completa?","it":"HarmonyAI può trasformare la musica in uno spartito completo?","zh":"HarmonyAI 能把音乐转成完整乐谱吗？"},"Пока нет. Это одна из самых сложных функций, над которой ведется работа. На сегодняшний день HarmonyAI умеет распознавать нотные диктанты, однако полноценное автоматическое преобразование любого музыкального произведения в профессиональную нотную запись пока находится в разработке. В будущем данная возможность обязательно появится.":{"en":"Not yet. This is one of the most complex features, and work on it is under way. Today HarmonyAI can recognise music dictations, but full automatic conversion of any piece into professional notation is still in development. This feature will definitely appear in the future.","fr":"Pas encore. C’est l’une des fonctions les plus complexes, et nous y travaillons. Aujourd’hui, HarmonyAI sait reconnaître des dictées musicales, mais la conversion automatique complète de n’importe quelle œuvre en partition professionnelle est encore en développement. Cette possibilité arrivera à coup sûr.","de":"Noch nicht. Das ist eine der schwierigsten Funktionen, an der gearbeitet wird. Heute erkennt HarmonyAI Musikdiktate, aber die vollständige automatische Umwandlung beliebiger Stücke in professionelle Noten ist noch in Entwicklung. Diese Möglichkeit wird künftig auf jeden Fall kommen.","es":"Todavía no. Es una de las funciones más complejas y estamos trabajando en ella. Hoy HarmonyAI reconoce dictados musicales, pero la conversión automática completa de cualquier obra en una partitura profesional sigue en desarrollo. Esta posibilidad llegará sin duda.","it":"Non ancora. È una delle funzioni più complesse e ci stiamo lavorando. Oggi HarmonyAI riconosce i dettati musicali, ma la conversione automatica completa di qualsiasi brano in una notazione professionale è ancora in sviluppo. Questa possibilità arriverà sicuramente.","zh":"暂时还不能。这是最复杂的功能之一，目前正在开发中。现在 HarmonyAI 已能识别听写练习，但把任意音乐作品自动转成专业乐谱仍在开发中。这项功能将来一定会推出。"},"Что входит в Pro-подписку?":{"en":"What does the Pro subscription include?","fr":"Que comprend l’abonnement Pro ?","de":"Was enthält das Pro-Abo?","es":"¿Qué incluye la suscripción Pro?","it":"Cosa include l’abbonamento Pro?","zh":"Pro 订阅包含什么？"},"Pro-подписка предоставляет доступ ко всем возможностям HarmonyAI без ограничений. Пользователи получают доступ к модели Dynatos, более качественной генерации изображений, функции распознавания музыки, отсутствию лимитов на использование сервиса, а также к новым функциям сразу после их официального выпуска. Кроме того, именно пользователи Pro первыми получают доступ к наиболее современным технологиям платформы.":{"en":"The Pro subscription gives access to all HarmonyAI features without restrictions: the Dynatos model, higher-quality image generation, music recognition, no usage limits, and new features as soon as they are officially released. Pro users are also the first to get the platform’s most advanced technologies.","fr":"L’abonnement Pro donne accès à toutes les fonctions de HarmonyAI sans restriction : le modèle Dynatos, une génération d’images de meilleure qualité, la reconnaissance musicale, l’absence de limites d’utilisation et les nouvelles fonctions dès leur sortie officielle. Les abonnés Pro sont aussi les premiers à profiter des technologies les plus récentes de la plateforme.","de":"Das Pro-Abo gibt uneingeschränkten Zugang zu allen Funktionen von HarmonyAI: das Modell Dynatos, hochwertigere Bilderzeugung, Musikerkennung, keine Nutzungslimits und neue Funktionen direkt nach ihrer offiziellen Veröffentlichung. Außerdem erhalten Pro-Nutzer als Erste Zugang zu den neuesten Technologien der Plattform.","es":"La suscripción Pro da acceso a todas las funciones de HarmonyAI sin restricciones: el modelo Dynatos, generación de imágenes de mayor calidad, reconocimiento musical, sin límites de uso y las nuevas funciones en cuanto se lanzan oficialmente. Además, los usuarios Pro son los primeros en acceder a las tecnologías más avanzadas de la plataforma.","it":"L’abbonamento Pro dà accesso a tutte le funzioni di HarmonyAI senza restrizioni: il modello Dynatos, una generazione di immagini di qualità superiore, il riconoscimento musicale, nessun limite d’uso e le nuove funzioni appena vengono rilasciate ufficialmente. Inoltre gli utenti Pro sono i primi ad accedere alle tecnologie più avanzate della piattaforma.","zh":"Pro 订阅可不受限制地使用 HarmonyAI 的全部功能：Dynatos 模型、更高质量的图片生成、音乐识别、无使用额度限制，并在新功能正式发布后立即可用。此外，Pro 用户还能率先体验平台最前沿的技术。"},"Чем бесплатная версия отличается от Pro?":{"en":"How is the free version different from Pro?","fr":"En quoi la version gratuite diffère-t-elle de Pro ?","de":"Worin unterscheidet sich die kostenlose Version von Pro?","es":"¿En qué se diferencia la versión gratuita de Pro?","it":"In cosa la versione gratuita differisce da Pro?","zh":"免费版与 Pro 有何区别？"},"Бесплатная версия позволяет познакомиться с основными возможностями HarmonyAI, однако имеет ряд ограничений. Используется менее мощная модель Adanatos, отсутствует распознавание музыки, генерация изображений имеет более низкое качество, а также действуют лимиты на использование. Pro-подписка снимает все эти ограничения и открывает полный функционал сервиса.":{"en":"The free version lets you get to know HarmonyAI’s main features but has a number of restrictions: it uses the less powerful Adanatos model, has no music recognition, image generation is of lower quality, and usage limits apply. The Pro subscription removes all of these restrictions and unlocks the full functionality of the service.","fr":"La version gratuite permet de découvrir les principales fonctions de HarmonyAI, mais comporte plusieurs restrictions : le modèle Adanatos, moins puissant, est utilisé, la reconnaissance musicale est absente, la génération d’images est de moindre qualité et des limites d’utilisation s’appliquent. L’abonnement Pro lève toutes ces restrictions et ouvre l’ensemble des fonctionnalités.","de":"Mit der kostenlosen Version lernen Sie die wichtigsten Funktionen von HarmonyAI kennen, sie hat jedoch Einschränkungen: Es wird das schwächere Modell Adanatos genutzt, Musikerkennung fehlt, die Bilderzeugung hat geringere Qualität, und es gelten Nutzungslimits. Das Pro-Abo hebt all diese Einschränkungen auf und schaltet den vollen Funktionsumfang frei.","es":"La versión gratuita permite conocer las funciones principales de HarmonyAI, pero tiene varias restricciones: usa el modelo Adanatos, menos potente, no incluye reconocimiento musical, la generación de imágenes es de menor calidad y se aplican límites de uso. La suscripción Pro elimina todas estas restricciones y desbloquea todas las funciones del servicio.","it":"La versione gratuita permette di conoscere le funzioni principali di HarmonyAI, ma ha alcune restrizioni: usa il modello Adanatos, meno potente, non include il riconoscimento musicale, la generazione di immagini è di qualità inferiore e valgono limiti d’uso. L’abbonamento Pro elimina tutte queste restrizioni e sblocca tutte le funzionalità del servizio.","zh":"免费版可以体验 HarmonyAI 的主要功能，但有一些限制：使用性能较弱的 Adanatos 模型，没有音乐识别，图片生成质量较低，并且有使用额度。Pro 订阅会解除所有这些限制，开放服务的全部功能。"},"Есть ли ограничения в бесплатной версии?":{"en":"Are there limits in the free version?","fr":"La version gratuite a-t-elle des limites ?","de":"Gibt es Einschränkungen in der kostenlosen Version?","es":"¿Hay límites en la versión gratuita?","it":"Ci sono limiti nella versione gratuita?","zh":"免费版有限制吗？"},"Да. Бесплатная версия HarmonyAI имеет ограничения по количеству запросов и некоторым функциям сервиса. Такие ограничения позволяют обеспечить стабильную работу платформы для всех пользователей. Если вам требуется постоянный доступ без лимитов, рекомендуется оформить Pro-подписку.":{"en":"Yes. The free version of HarmonyAI is limited in the number of requests and some features. These limits keep the platform stable for all users. If you need constant access without limits, we recommend the Pro subscription.","fr":"Oui. La version gratuite de HarmonyAI est limitée en nombre de requêtes et pour certaines fonctions. Ces limites garantissent un fonctionnement stable de la plateforme pour tous. Si vous avez besoin d’un accès permanent sans limites, nous vous conseillons l’abonnement Pro.","de":"Ja. Die kostenlose Version von HarmonyAI ist bei der Anzahl der Anfragen und bei einigen Funktionen eingeschränkt. So bleibt die Plattform für alle Nutzer stabil. Brauchen Sie dauerhaften Zugang ohne Limits, empfehlen wir das Pro-Abo.","es":"Sí. La versión gratuita de HarmonyAI tiene límites de solicitudes y de algunas funciones. Estos límites garantizan que la plataforma funcione de forma estable para todos. Si necesitas acceso continuo sin límites, te recomendamos la suscripción Pro.","it":"Sì. La versione gratuita di HarmonyAI ha limiti sul numero di richieste e su alcune funzioni. Questi limiti garantiscono un funzionamento stabile della piattaforma per tutti. Se ti serve un accesso continuo senza limiti, ti consigliamo l’abbonamento Pro.","zh":"有。HarmonyAI 免费版对请求次数和部分功能有限制，以确保平台对所有用户都稳定运行。如果你需要不受限制的持续使用，建议开通 Pro 订阅。"},"Как оформить подписку?":{"en":"How do I subscribe?","fr":"Comment s’abonner ?","de":"Wie schließe ich ein Abo ab?","es":"¿Cómo me suscribo?","it":"Come ci si abbona?","zh":"如何开通订阅？"},"Для оформления подписки откройте раздел «Настройки» и выберите пункт «Обновить подписку». Также оформить Pro можно на официальном сайте:":{"en":"To subscribe, open “Settings” and choose “Upgrade subscription”. You can also get Pro on the official website:","fr":"Pour vous abonner, ouvrez « Paramètres » et choisissez « Mettre à jour l’abonnement ». Vous pouvez aussi souscrire à Pro sur le site officiel :","de":"Öffnen Sie dazu „Einstellungen“ und wählen Sie „Abo aktualisieren“. Pro können Sie auch auf der offiziellen Website abschließen:","es":"Para suscribirte, abre «Configuración» y elige «Mejorar suscripción». También puedes obtener Pro en el sitio oficial:","it":"Per abbonarti, apri «Impostazioni» e scegli «Aggiorna abbonamento». Puoi anche attivare Pro sul sito ufficiale:","zh":"开通订阅：打开“设置”，选择“升级订阅”。也可以在官方网站开通 Pro："},". После успешной оплаты подписка автоматически активируется для вашего аккаунта.":{"en":". After successful payment, the subscription is activated for your account automatically.","fr":". Après le paiement, l’abonnement est automatiquement activé sur votre compte.","de":". Nach erfolgreicher Zahlung wird das Abo automatisch für Ihr Konto aktiviert.","es":". Tras el pago, la suscripción se activa automáticamente en tu cuenta.","it":". Dopo il pagamento, l’abbonamento si attiva automaticamente sul tuo account.","zh":"。支付成功后，订阅会自动在你的账户中生效。"},"Как отменить подписку?":{"en":"How do I cancel my subscription?","fr":"Comment résilier l’abonnement ?","de":"Wie kündige ich das Abo?","es":"¿Cómo cancelo la suscripción?","it":"Come annullo l’abbonamento?","zh":"如何取消订阅？"},"Если вы хотите отменить подписку, необходимо обратиться в службу поддержки. Специалисты помогут отключить автоматическое продление и ответят на все вопросы, связанные с подпиской. Ссылка на поддержку будет добавлена позднее.":{"en":"If you want to cancel your subscription, contact support. Our team will help turn off auto-renewal and answer any subscription questions. A link to support will be added later.","fr":"Pour résilier l’abonnement, contactez l’assistance. Nos spécialistes désactiveront le renouvellement automatique et répondront à toutes vos questions. Le lien vers l’assistance sera ajouté ultérieurement.","de":"Möchten Sie das Abo kündigen, wenden Sie sich an den Support. Das Team deaktiviert die automatische Verlängerung und beantwortet alle Fragen zum Abo. Ein Link zum Support wird später ergänzt.","es":"Si quieres cancelar la suscripción, contacta con soporte. El equipo desactivará la renovación automática y resolverá tus dudas sobre la suscripción. El enlace al soporte se añadirá más adelante.","it":"Se vuoi annullare l’abbonamento, contatta l’assistenza. Il team disattiverà il rinnovo automatico e risponderà a tutte le domande sull’abbonamento. Il link all’assistenza verrà aggiunto in seguito.","zh":"如需取消订阅，请联系客服。工作人员会帮你关闭自动续费并解答订阅相关问题。客服链接稍后添加。"},"Можно ли вернуть деньги за подписку?":{"en":"Can I get a refund for the subscription?","fr":"Peut-on se faire rembourser l’abonnement ?","de":"Kann ich das Abo erstattet bekommen?","es":"¿Me pueden devolver el dinero de la suscripción?","it":"Posso ottenere un rimborso dell’abbonamento?","zh":"订阅可以退款吗？"},"Нет. После успешной оплаты стоимость подписки не возвращается. Перед оформлением рекомендуется внимательно ознакомиться с возможностями выбранного тарифа. Если во время оплаты произошел технический сбой, необходимо обратиться в службу поддержки для индивидуального рассмотрения ситуации.":{"en":"No. Once paid, the subscription fee is not refunded. Before subscribing, please review the features of the chosen plan carefully. If a technical failure occurred during payment, contact support so the situation can be reviewed individually.","fr":"Non. Une fois le paiement effectué, le prix de l’abonnement n’est pas remboursé. Avant de souscrire, prenez connaissance des possibilités de la formule choisie. En cas de problème technique pendant le paiement, contactez l’assistance pour un examen individuel.","de":"Nein. Nach erfolgreicher Zahlung wird der Abopreis nicht erstattet. Informieren Sie sich vor dem Abschluss genau über den gewählten Tarif. Ist bei der Zahlung ein technischer Fehler aufgetreten, wenden Sie sich an den Support, damit der Fall einzeln geprüft wird.","es":"No. Una vez realizado el pago, el importe de la suscripción no se devuelve. Antes de suscribirte, revisa con atención las funciones del plan elegido. Si hubo un fallo técnico durante el pago, contacta con soporte para estudiar tu caso.","it":"No. Dopo il pagamento il costo dell’abbonamento non viene rimborsato. Prima di abbonarti, verifica con attenzione le funzioni del piano scelto. Se durante il pagamento si è verificato un errore tecnico, contatta l’assistenza per un esame individuale.","zh":"不可以。支付成功后，订阅费用不予退还。开通前请仔细了解所选套餐的功能。如果支付过程中出现技术故障，请联系客服进行个案处理。"},"Какие способы оплаты доступны?":{"en":"Which payment methods are available?","fr":"Quels moyens de paiement sont disponibles ?","de":"Welche Zahlungsmethoden gibt es?","es":"¿Qué métodos de pago hay?","it":"Quali metodi di pagamento sono disponibili?","zh":"支持哪些支付方式？"},"На данный момент оплатить подписку можно банковской картой платежной системы «Мир» или через Систему быстрых платежей (СБП). В будущем список доступных способов оплаты может быть расширен.":{"en":"Currently you can pay for the subscription with a Mir payment system bank card or via the Faster Payments System (SBP). The list of payment methods may be expanded in the future.","fr":"Actuellement, l’abonnement peut être payé par carte bancaire du système de paiement « Mir » ou via le Système de paiements rapides (SBP). La liste des moyens de paiement pourra être élargie.","de":"Derzeit kann das Abo mit einer Bankkarte des Zahlungssystems „Mir“ oder über das Schnellzahlungssystem (SBP) bezahlt werden. Künftig können weitere Zahlungsmethoden hinzukommen.","es":"Por ahora, la suscripción se puede pagar con tarjeta bancaria del sistema de pago Mir o mediante el Sistema de Pagos Rápidos (SBP). En el futuro se podrán añadir otros métodos.","it":"Al momento l’abbonamento si può pagare con carta bancaria del circuito «Mir» o tramite il Sistema di pagamenti rapidi (SBP). In futuro l’elenco dei metodi di pagamento potrebbe ampliarsi.","zh":"目前可使用 Mir 支付系统的银行卡或快速支付系统（SBP）支付订阅费用。未来可能增加更多支付方式。"},"Сохраняются ли мои сообщения?":{"en":"Are my messages saved?","fr":"Mes messages sont-ils conservés ?","de":"Werden meine Nachrichten gespeichert?","es":"¿Se guardan mis mensajes?","it":"I miei messaggi vengono salvati?","zh":"我的消息会被保存吗？"},"Да. История ваших диалогов сохраняется в аккаунте, чтобы вы могли продолжить общение в любой момент с любого устройства. Все сообщения обрабатываются конфиденциально. Часть обезличенных данных может использоваться для улучшения качества работы искусственного интеллекта и повышения точности ответов.":{"en":"Yes. Your conversation history is saved in your account so you can continue at any time from any device. All messages are processed confidentially. Some anonymised data may be used to improve the AI and the accuracy of its answers.","fr":"Oui. L’historique de vos conversations est conservé dans votre compte pour que vous puissiez reprendre à tout moment depuis n’importe quel appareil. Tous les messages sont traités de manière confidentielle. Une partie des données anonymisées peut servir à améliorer l’IA et la précision des réponses.","de":"Ja. Ihr Chatverlauf wird im Konto gespeichert, damit Sie jederzeit und auf jedem Gerät weitermachen können. Alle Nachrichten werden vertraulich verarbeitet. Ein Teil der anonymisierten Daten kann zur Verbesserung der KI und der Genauigkeit der Antworten genutzt werden.","es":"Sí. El historial de tus conversaciones se guarda en tu cuenta para que puedas continuar en cualquier momento y desde cualquier dispositivo. Todos los mensajes se tratan de forma confidencial. Parte de los datos anonimizados puede usarse para mejorar la IA y la precisión de las respuestas.","it":"Sì. La cronologia delle conversazioni viene salvata nel tuo account, così puoi riprendere in qualsiasi momento da qualsiasi dispositivo. Tutti i messaggi sono trattati in modo riservato. Una parte dei dati anonimizzati può essere usata per migliorare l’IA e la precisione delle risposte.","zh":"会。你的对话记录保存在账户中，可随时在任何设备上继续。所有消息均保密处理。部分匿名化数据可能会用于改进 AI 和提高回答准确性。"},"Кто может видеть мои данные?":{"en":"Who can see my data?","fr":"Qui peut voir mes données ?","de":"Wer kann meine Daten sehen?","es":"¿Quién puede ver mis datos?","it":"Chi può vedere i miei dati?","zh":"谁能看到我的数据？"},"Ваши данные обрабатываются конфиденциально и используются исключительно в рамках работы сервиса. HarmonyAI не публикует ваши переписки и не предоставляет к ним открытый доступ. Мы уделяем большое внимание безопасности пользовательских данных.":{"en":"Your data is processed confidentially and used only to operate the service. HarmonyAI does not publish your conversations or make them publicly accessible. We take the security of user data very seriously.","fr":"Vos données sont traitées de manière confidentielle et utilisées uniquement pour le fonctionnement du service. HarmonyAI ne publie pas vos conversations et n’y donne pas d’accès public. Nous accordons une grande attention à la sécurité des données des utilisateurs.","de":"Ihre Daten werden vertraulich verarbeitet und ausschließlich für den Betrieb des Dienstes verwendet. HarmonyAI veröffentlicht Ihre Chats nicht und macht sie nicht öffentlich zugänglich. Die Sicherheit der Nutzerdaten hat für uns hohe Priorität.","es":"Tus datos se tratan de forma confidencial y solo se usan para el funcionamiento del servicio. HarmonyAI no publica tus conversaciones ni permite el acceso público a ellas. Prestamos mucha atención a la seguridad de los datos de los usuarios.","it":"I tuoi dati sono trattati in modo riservato e usati esclusivamente per il funzionamento del servizio. HarmonyAI non pubblica le tue conversazioni e non le rende accessibili pubblicamente. Prestiamo grande attenzione alla sicurezza dei dati degli utenti.","zh":"你的数据会被保密处理，仅用于服务运行。HarmonyAI 不会公开你的对话，也不会提供公开访问。我们非常重视用户数据的安全。"},"Используются ли мои данные для улучшения искусственного интеллекта?":{"en":"Is my data used to improve the AI?","fr":"Mes données servent-elles à améliorer l’IA ?","de":"Werden meine Daten zur Verbesserung der KI genutzt?","es":"¿Se usan mis datos para mejorar la IA?","it":"I miei dati vengono usati per migliorare l’IA?","zh":"我的数据会被用来改进 AI 吗？"},"Да. Некоторые обезличенные данные могут использоваться для повышения качества ответов, исправления ошибок и дальнейшего развития HarmonyAI. Это помогает искусственному интеллекту становиться умнее и полезнее для всех пользователей.":{"en":"Yes. Some anonymised data may be used to improve the quality of answers, fix errors and further develop HarmonyAI. This helps the AI become smarter and more useful for all users.","fr":"Oui. Certaines données anonymisées peuvent servir à améliorer la qualité des réponses, à corriger des erreurs et à poursuivre le développement de HarmonyAI. Cela aide l’IA à devenir plus intelligente et plus utile pour tous.","de":"Ja. Einige anonymisierte Daten können genutzt werden, um die Qualität der Antworten zu verbessern, Fehler zu beheben und HarmonyAI weiterzuentwickeln. So wird die KI klüger und für alle Nutzer hilfreicher.","es":"Sí. Algunos datos anonimizados pueden usarse para mejorar la calidad de las respuestas, corregir errores y seguir desarrollando HarmonyAI. Así la IA se vuelve más inteligente y útil para todos.","it":"Sì. Alcuni dati anonimizzati possono essere usati per migliorare la qualità delle risposte, correggere errori e sviluppare ulteriormente HarmonyAI. Questo aiuta l’IA a diventare più intelligente e utile per tutti.","zh":"会。部分匿名化数据可能用于提高回答质量、修复错误和进一步发展 HarmonyAI，让 AI 对所有用户都更聪明、更有用。"},"Можно ли удалить историю чатов?":{"en":"Can I delete my chat history?","fr":"Puis-je supprimer l’historique des conversations ?","de":"Kann ich den Chatverlauf löschen?","es":"¿Puedo borrar el historial de chats?","it":"Posso eliminare la cronologia delle chat?","zh":"可以删除聊天记录吗？"},"Да. Вы можете удалить историю своих диалогов. После удаления чаты больше не будут отображаться в вашем аккаунте. Некоторые технические данные могут временно храниться в соответствии с требованиями безопасности и действующей Политикой конфиденциальности.":{"en":"Yes. You can delete your conversation history. After deletion, the chats no longer appear in your account. Some technical data may be kept temporarily in accordance with security requirements and the current Privacy Policy.","fr":"Oui. Vous pouvez supprimer l’historique de vos conversations. Une fois supprimées, elles n’apparaissent plus dans votre compte. Certaines données techniques peuvent être conservées temporairement conformément aux exigences de sécurité et à la Politique de confidentialité en vigueur.","de":"Ja. Sie können Ihren Chatverlauf löschen. Danach werden die Chats nicht mehr in Ihrem Konto angezeigt. Einige technische Daten können gemäß Sicherheitsanforderungen und der geltenden Datenschutzerklärung vorübergehend gespeichert bleiben.","es":"Sí. Puedes borrar el historial de tus conversaciones. Tras borrarlos, los chats dejan de mostrarse en tu cuenta. Algunos datos técnicos pueden conservarse temporalmente según los requisitos de seguridad y la Política de privacidad vigente.","it":"Sì. Puoi eliminare la cronologia delle conversazioni. Dopo l’eliminazione le chat non compaiono più nel tuo account. Alcuni dati tecnici possono essere conservati temporaneamente secondo i requisiti di sicurezza e l’Informativa sulla privacy in vigore.","zh":"可以。你可以删除对话记录，删除后这些对话将不再显示在账户中。根据安全要求和现行《隐私政策》，部分技术数据可能会暂时保留。"},"Насколько безопасно пользоваться HarmonyAI?":{"en":"How safe is it to use HarmonyAI?","fr":"L’utilisation de HarmonyAI est-elle sûre ?","de":"Wie sicher ist die Nutzung von HarmonyAI?","es":"¿Es seguro usar HarmonyAI?","it":"Quanto è sicuro usare HarmonyAI?","zh":"使用 HarmonyAI 安全吗？"},"Безопасность пользователей является одним из главных приоритетов проекта. Все данные обрабатываются конфиденциально, а передача информации осуществляется по защищенным соединениям. Мы рекомендуем не отправлять в чат банковские данные, пароли и другую особо важную личную информацию. Подробнее ознакомиться с обработкой данных можно в Политике конфиденциальности, которая доступна в настройках приложения.":{"en":"User security is one of the project’s top priorities. All data is processed confidentially and transmitted over secure connections. We recommend not sending bank details, passwords or other highly sensitive personal information in the chat. You can learn more about data processing in the Privacy Policy, available in the app settings.","fr":"La sécurité des utilisateurs est l’une des priorités du projet. Toutes les données sont traitées de manière confidentielle et transmises via des connexions sécurisées. Nous vous recommandons de ne pas envoyer dans le chat de données bancaires, de mots de passe ou d’autres informations personnelles sensibles. Pour en savoir plus sur le traitement des données, consultez la Politique de confidentialité, disponible dans les paramètres de l’application.","de":"Die Sicherheit der Nutzer hat für das Projekt höchste Priorität. Alle Daten werden vertraulich verarbeitet und über geschützte Verbindungen übertragen. Wir empfehlen, keine Bankdaten, Passwörter oder andere besonders sensible persönliche Informationen im Chat zu senden. Mehr zur Datenverarbeitung finden Sie in der Datenschutzerklärung in den Einstellungen der App.","es":"La seguridad de los usuarios es una de las prioridades del proyecto. Todos los datos se tratan de forma confidencial y se transmiten por conexiones seguras. Te recomendamos no enviar al chat datos bancarios, contraseñas ni otra información personal especialmente sensible. Puedes saber más sobre el tratamiento de datos en la Política de privacidad, disponible en la configuración de la aplicación.","it":"La sicurezza degli utenti è una delle priorità del progetto. Tutti i dati sono trattati in modo riservato e trasmessi tramite connessioni protette. Ti consigliamo di non inviare in chat dati bancari, password o altre informazioni personali particolarmente sensibili. Per saperne di più sul trattamento dei dati, consulta l’Informativa sulla privacy, disponibile nelle impostazioni dell’app.","zh":"用户安全是本项目的首要任务之一。所有数据均保密处理，并通过加密连接传输。建议不要在聊天中发送银行信息、密码等重要个人信息。更多数据处理信息，请参阅应用设置中的《隐私政策》。"},"Почему искусственный интеллект может ошибаться?":{"en":"Why can the AI make mistakes?","fr":"Pourquoi l’IA peut-elle se tromper ?","de":"Warum kann die KI Fehler machen?","es":"¿Por qué puede equivocarse la IA?","it":"Perché l’IA può sbagliare?","zh":"为什么 AI 会出错？"},"HarmonyAI обучен на большом количестве данных, включая специализированные материалы по музыкальной грамоте, однако ни один искусственный интеллект не может знать абсолютно все. Иногда модель может неправильно понять вопрос, использовать устаревшую информацию или сделать неверный вывод. Особенно это касается сложных или неоднозначных запросов. Если ответ кажется вам сомнительным, рекомендуем проверить информацию по дополнительным источникам или сообщить об ошибке через систему обратной связи. Ваши отзывы помогают сделать HarmonyAI лучше с каждым обновлением.":{"en":"HarmonyAI has been trained on a large amount of data, including specialised music theory materials, but no AI can know absolutely everything. Sometimes the model may misunderstand a question, use outdated information or draw the wrong conclusion, especially with complex or ambiguous requests. If an answer seems doubtful, check the information in other sources or report the error through the feedback system. Your feedback helps make HarmonyAI better with every update.","fr":"HarmonyAI a été entraînée sur une grande quantité de données, y compris des contenus spécialisés en formation musicale, mais aucune IA ne peut tout savoir. Il arrive que le modèle comprenne mal une question, utilise une information dépassée ou tire une mauvaise conclusion, surtout pour des demandes complexes ou ambiguës. Si une réponse vous paraît douteuse, vérifiez-la auprès d’autres sources ou signalez l’erreur via le système de retours. Vos avis aident à améliorer HarmonyAI à chaque mise à jour.","de":"HarmonyAI wurde mit sehr vielen Daten trainiert, darunter Fachmaterial zur Musiklehre, doch keine KI kann absolut alles wissen. Manchmal versteht das Modell eine Frage falsch, nutzt veraltete Informationen oder zieht einen falschen Schluss, besonders bei komplexen oder mehrdeutigen Anfragen. Wirkt eine Antwort zweifelhaft, prüfen Sie die Information in weiteren Quellen oder melden Sie den Fehler über das Feedback-System. Ihr Feedback hilft, HarmonyAI mit jedem Update besser zu machen.","es":"HarmonyAI se ha entrenado con una gran cantidad de datos, incluidos materiales especializados de lenguaje musical, pero ninguna IA lo sabe absolutamente todo. A veces el modelo puede entender mal una pregunta, usar información desactualizada o sacar una conclusión equivocada, sobre todo con peticiones complejas o ambiguas. Si una respuesta te parece dudosa, compruébala en otras fuentes o informa del error mediante el sistema de comentarios. Tus opiniones ayudan a mejorar HarmonyAI con cada actualización.","it":"HarmonyAI è stata addestrata su una grande quantità di dati, compresi materiali specialistici di teoria musicale, ma nessuna IA può sapere proprio tutto. A volte il modello può fraintendere una domanda, usare informazioni superate o trarre una conclusione sbagliata, soprattutto con richieste complesse o ambigue. Se una risposta ti sembra dubbia, verifica l’informazione con altre fonti o segnala l’errore tramite il sistema di feedback. I tuoi commenti aiutano a migliorare HarmonyAI a ogni aggiornamento.","zh":"HarmonyAI 使用了大量数据训练，包括音乐基础知识方面的专业资料，但没有任何 AI 能无所不知。模型有时可能误解问题、使用过时信息或得出错误结论，尤其是在问题复杂或含糊时。如果觉得回答可疑，建议通过其他来源核实，或通过反馈系统报告错误。你的反馈会让 HarmonyAI 在每次更新中变得更好。"},"Что делать, если ответ оказался неправильным?":{"en":"What should I do if an answer is wrong?","fr":"Que faire si une réponse est fausse ?","de":"Was tun, wenn eine Antwort falsch ist?","es":"¿Qué hago si una respuesta es incorrecta?","it":"Cosa fare se una risposta è sbagliata?","zh":"如果回答错了怎么办？"},"Если вы получили неверный ответ, поставьте ему дизлайк и, по возможности, укажите правильный вариант. Эта информация помогает улучшать качество работы искусственного интеллекта. Если ошибка серьезная или повторяется несколько раз, вы также можете обратиться в службу поддержки, подробно описав ситуацию. Каждое сообщение рассматривается разработчиками.":{"en":"If you get a wrong answer, give it a dislike and, if possible, provide the correct version. This information helps improve the AI. If the error is serious or repeats several times, you can also contact support with a detailed description. Every message is reviewed by the developers.","fr":"Si vous obtenez une réponse erronée, mettez-lui un « je n’aime pas » et, si possible, indiquez la bonne réponse. Cela aide à améliorer l’IA. Si l’erreur est grave ou se répète, vous pouvez aussi contacter l’assistance en décrivant la situation en détail. Chaque message est examiné par les développeurs.","de":"Wenn Sie eine falsche Antwort erhalten, geben Sie ein „Gefällt mir nicht“ und nennen Sie nach Möglichkeit die richtige Variante. Das hilft, die KI zu verbessern. Ist der Fehler gravierend oder tritt er wiederholt auf, können Sie sich mit einer genauen Beschreibung auch an den Support wenden. Jede Nachricht wird von den Entwicklern geprüft.","es":"Si recibes una respuesta incorrecta, márcala con «no me gusta» y, si puedes, indica la respuesta correcta. Esta información ayuda a mejorar la IA. Si el error es grave o se repite, también puedes escribir a soporte describiendo la situación en detalle. Los desarrolladores revisan cada mensaje.","it":"Se ricevi una risposta sbagliata, metti «non mi piace» e, se possibile, indica la versione corretta. Questa informazione aiuta a migliorare l’IA. Se l’errore è grave o si ripete più volte, puoi anche contattare l’assistenza descrivendo la situazione nel dettaglio. Ogni messaggio viene esaminato dagli sviluppatori.","zh":"如果收到错误的回答，请点“不喜欢”，并尽可能给出正确答案。这些信息有助于改进 AI。如果错误严重或多次出现，也可以联系客服并详细描述情况。开发者会查看每一条反馈。"},"Как сообщить об ошибке?":{"en":"How do I report an error?","fr":"Comment signaler une erreur ?","de":"Wie melde ich einen Fehler?","es":"¿Cómo informo de un error?","it":"Come segnalo un errore?","zh":"如何报告错误？"},"Сообщить об ошибке можно непосредственно в приложении или через официального Telegram-бота поддержки. При обращении желательно максимально подробно описать проблему и, если возможно, приложить скриншоты или пример запроса. Это поможет быстрее разобраться в ситуации и исправить ошибку.":{"en":"You can report an error right in the app or through the official Telegram support bot. Describe the problem in as much detail as possible and, if you can, attach screenshots or an example request. This helps us understand the situation faster and fix the error.","fr":"Vous pouvez signaler une erreur directement dans l’application ou via le bot d’assistance Telegram officiel. Décrivez le problème le plus précisément possible et, si vous le pouvez, joignez des captures d’écran ou un exemple de requête. Cela nous aide à comprendre plus vite et à corriger l’erreur.","de":"Einen Fehler können Sie direkt in der App oder über den offiziellen Telegram-Support-Bot melden. Beschreiben Sie das Problem möglichst genau und fügen Sie nach Möglichkeit Screenshots oder eine Beispielanfrage bei. So können wir die Situation schneller verstehen und den Fehler beheben.","es":"Puedes informar de un error directamente en la aplicación o a través del bot oficial de soporte en Telegram. Describe el problema con el mayor detalle posible y, si puedes, adjunta capturas de pantalla o un ejemplo de la petición. Así entenderemos antes la situación y corregiremos el error.","it":"Puoi segnalare un errore direttamente nell’app o tramite il bot ufficiale di assistenza su Telegram. Descrivi il problema nel modo più dettagliato possibile e, se puoi, allega screenshot o un esempio di richiesta. Così capiremo più in fretta la situazione e correggeremo l’errore.","zh":"可以直接在应用内报告错误，也可以通过官方 Telegram 客服机器人反馈。请尽量详细描述问题，如有可能请附上截图或请求示例，这样我们能更快弄清情况并修复错误。"},"Есть ли возрастные ограничения?":{"en":"Are there age restrictions?","fr":"Y a-t-il des restrictions d’âge ?","de":"Gibt es Altersbeschränkungen?","es":"¿Hay restricciones de edad?","it":"Ci sono limiti di età?","zh":"有年龄限制吗？"},"Пользоваться HarmonyAI можно с 10 лет. Если пользователю еще не исполнилось 18 лет, использование сервиса должно осуществляться с разрешения родителей или законных представителей. Это связано с требованиями пользовательского соглашения и правилами использования сервиса.":{"en":"HarmonyAI can be used from the age of 10. Users under 18 must use the service with the permission of their parents or legal guardians. This follows from the user agreement and the rules for using the service.","fr":"HarmonyAI peut être utilisée dès 10 ans. Si l’utilisateur a moins de 18 ans, l’utilisation du service doit se faire avec l’autorisation de ses parents ou représentants légaux. Cela découle des exigences du contrat d’utilisation et des règles du service.","de":"HarmonyAI kann ab 10 Jahren genutzt werden. Nutzer unter 18 Jahren dürfen den Dienst nur mit Erlaubnis der Eltern oder gesetzlichen Vertreter verwenden. Das ergibt sich aus der Nutzungsvereinbarung und den Nutzungsregeln des Dienstes.","es":"HarmonyAI se puede usar a partir de los 10 años. Si el usuario es menor de 18 años, debe usar el servicio con permiso de sus padres o representantes legales. Así lo exigen el acuerdo de usuario y las normas de uso del servicio.","it":"HarmonyAI si può usare dai 10 anni. Se l’utente non ha ancora 18 anni, il servizio va usato con il permesso dei genitori o dei rappresentanti legali. Lo prevedono l’accordo d’uso e le regole di utilizzo del servizio.","zh":"HarmonyAI 适合 10 岁及以上的用户使用。未满 18 岁的用户须在父母或法定监护人许可下使用本服务。这是用户协议和服务使用规则的要求。"},"Почему HarmonyAI находится в стадии бета-тестирования?":{"en":"Why is HarmonyAI in beta?","fr":"Pourquoi HarmonyAI est-elle en version bêta ?","de":"Warum ist HarmonyAI in der Beta-Phase?","es":"¿Por qué HarmonyAI está en fase beta?","it":"Perché HarmonyAI è in beta?","zh":"为什么 HarmonyAI 还在测试阶段？"},"HarmonyAI активно развивается, поэтому некоторые функции продолжают дорабатываться и совершенствоваться. Бета-тестирование позволяет быстрее находить ошибки, улучшать качество ответов и добавлять новые возможности. Чем больше пользователей пользуются сервисом и поддерживают его развитие, тем быстрее появляются новые функции и становится лучше качество работы искусственного интеллекта.":{"en":"HarmonyAI is developing actively, so some features are still being refined and improved. Beta testing helps us find errors faster, improve the quality of answers and add new features. The more people use the service and support its development, the faster new features appear and the better the AI becomes.","fr":"HarmonyAI évolue activement : certaines fonctions sont encore en cours de finition et d’amélioration. La phase bêta permet de trouver plus vite les erreurs, d’améliorer la qualité des réponses et d’ajouter de nouvelles possibilités. Plus les utilisateurs sont nombreux à utiliser le service et à soutenir son développement, plus les nouvelles fonctions arrivent vite et plus l’IA progresse.","de":"HarmonyAI wird aktiv weiterentwickelt, daher werden einige Funktionen noch verfeinert und verbessert. Die Beta-Phase hilft, Fehler schneller zu finden, die Qualität der Antworten zu verbessern und neue Möglichkeiten hinzuzufügen. Je mehr Menschen den Dienst nutzen und seine Entwicklung unterstützen, desto schneller kommen neue Funktionen und desto besser wird die KI.","es":"HarmonyAI está en pleno desarrollo, así que algunas funciones todavía se están puliendo y mejorando. La fase beta permite encontrar errores antes, mejorar la calidad de las respuestas y añadir nuevas funciones. Cuantas más personas usen el servicio y apoyen su desarrollo, antes llegarán las novedades y mejor funcionará la IA.","it":"HarmonyAI è in pieno sviluppo, quindi alcune funzioni sono ancora in fase di rifinitura e miglioramento. La fase beta permette di trovare più rapidamente gli errori, migliorare la qualità delle risposte e aggiungere nuove possibilità. Più persone usano il servizio e ne sostengono lo sviluppo, più rapidamente arrivano nuove funzioni e migliore diventa l’IA.","zh":"HarmonyAI 正在积极发展，部分功能仍在完善中。测试阶段能帮助我们更快发现错误、提升回答质量并增加新功能。使用和支持本服务的用户越多，新功能上线越快，AI 的表现也会越好。"},"На каких устройствах работает HarmonyAI?":{"en":"Which devices does HarmonyAI work on?","fr":"Sur quels appareils HarmonyAI fonctionne-t-elle ?","de":"Auf welchen Geräten funktioniert HarmonyAI?","es":"¿En qué dispositivos funciona HarmonyAI?","it":"Su quali dispositivi funziona HarmonyAI?","zh":"HarmonyAI 支持哪些设备？"},"HarmonyAI работает практически на любом современном устройстве. Вы можете пользоваться сервисом на смартфонах Android и iPhone, планшетах, компьютерах под управлением Windows, macOS и Linux. Для работы достаточно любого современного браузера и подключения к интернету. Установка дополнительных программ не требуется.":{"en":"HarmonyAI works on almost any modern device: Android phones and iPhones, tablets, and computers running Windows, macOS and Linux. All you need is a modern browser and an internet connection. No extra software is required.","fr":"HarmonyAI fonctionne sur presque tous les appareils récents : smartphones Android et iPhone, tablettes, ordinateurs sous Windows, macOS et Linux. Un navigateur récent et une connexion Internet suffisent. Aucun logiciel supplémentaire n’est nécessaire.","de":"HarmonyAI läuft auf fast jedem modernen Gerät: Android-Smartphones und iPhones, Tablets, Computer mit Windows, macOS und Linux. Sie brauchen nur einen aktuellen Browser und eine Internetverbindung. Zusätzliche Programme sind nicht nötig.","es":"HarmonyAI funciona en casi cualquier dispositivo actual: móviles Android y iPhone, tabletas y ordenadores con Windows, macOS y Linux. Basta con un navegador moderno y conexión a internet. No hace falta instalar nada más.","it":"HarmonyAI funziona su quasi tutti i dispositivi moderni: smartphone Android e iPhone, tablet, computer con Windows, macOS e Linux. Bastano un browser aggiornato e una connessione a Internet. Non servono programmi aggiuntivi.","zh":"HarmonyAI 几乎适用于所有现代设备：Android 手机和 iPhone、平板电脑，以及运行 Windows、macOS 和 Linux 的电脑。只需一个现代浏览器和网络连接，无需安装其他软件。"},"Есть ли мобильное приложение?":{"en":"Is there a mobile app?","fr":"Existe-t-il une application mobile ?","de":"Gibt es eine mobile App?","es":"¿Hay aplicación móvil?","it":"Esiste un’app mobile?","zh":"有手机应用吗？"},"Пока нет. В настоящее время HarmonyAI работает как современное веб-приложение, которое полностью адаптировано под мобильные устройства. В будущем планируется выпуск полноценных приложений для Android и iOS с еще более удобным интерфейсом и дополнительными возможностями.":{"en":"Not yet. HarmonyAI currently works as a modern web app fully adapted for mobile devices. Full apps for Android and iOS with an even more convenient interface and extra features are planned for the future.","fr":"Pas encore. Pour l’instant, HarmonyAI fonctionne comme une application web moderne entièrement adaptée aux appareils mobiles. Des applications complètes pour Android et iOS, avec une interface encore plus pratique et des fonctions supplémentaires, sont prévues.","de":"Noch nicht. Derzeit läuft HarmonyAI als moderne Web-App, die vollständig an Mobilgeräte angepasst ist. Vollwertige Apps für Android und iOS mit noch bequemerer Oberfläche und Zusatzfunktionen sind geplant.","es":"Todavía no. Por ahora HarmonyAI funciona como una aplicación web moderna totalmente adaptada a móviles. Está previsto lanzar aplicaciones completas para Android e iOS con una interfaz aún más cómoda y funciones adicionales.","it":"Non ancora. Attualmente HarmonyAI funziona come una moderna web app, completamente adattata ai dispositivi mobili. In futuro sono previste app complete per Android e iOS con un’interfaccia ancora più comoda e funzioni aggiuntive.","zh":"暂时还没有。目前 HarmonyAI 是一款完全适配移动设备的现代网页应用。未来计划推出功能更丰富、界面更便捷的 Android 和 iOS 应用。"},"Работает ли HarmonyAI на iPhone и Android?":{"en":"Does HarmonyAI work on iPhone and Android?","fr":"HarmonyAI fonctionne-t-elle sur iPhone et Android ?","de":"Funktioniert HarmonyAI auf iPhone und Android?","es":"¿Funciona HarmonyAI en iPhone y Android?","it":"HarmonyAI funziona su iPhone e Android?","zh":"HarmonyAI 能在 iPhone 和 Android 上使用吗？"},"Да. HarmonyAI полностью поддерживает работу на устройствах под управлением iOS и Android. Благодаря адаптивному интерфейсу сервис одинаково удобно использовать как на смартфонах, так и на планшетах.":{"en":"Yes. HarmonyAI fully supports iOS and Android devices. Thanks to its adaptive interface, the service is just as convenient on smartphones as on tablets.","fr":"Oui. HarmonyAI fonctionne pleinement sur les appareils iOS et Android. Grâce à son interface adaptative, le service est aussi pratique sur smartphone que sur tablette.","de":"Ja. HarmonyAI unterstützt iOS- und Android-Geräte vollständig. Dank der adaptiven Oberfläche ist der Dienst auf Smartphones genauso bequem wie auf Tablets.","es":"Sí. HarmonyAI funciona plenamente en dispositivos iOS y Android. Gracias a su interfaz adaptable, es igual de cómodo en móviles que en tabletas.","it":"Sì. HarmonyAI supporta pienamente i dispositivi iOS e Android. Grazie all’interfaccia adattiva, il servizio è comodo sia su smartphone sia su tablet.","zh":"可以。HarmonyAI 完全支持 iOS 和 Android 设备，自适应界面让它在手机和平板上同样好用。"},"Какие браузеры поддерживаются?":{"en":"Which browsers are supported?","fr":"Quels navigateurs sont pris en charge ?","de":"Welche Browser werden unterstützt?","es":"¿Qué navegadores se admiten?","it":"Quali browser sono supportati?","zh":"支持哪些浏览器？"},"HarmonyAI работает во всех современных браузерах, поддерживающих актуальные веб-стандарты. Если ваш браузер регулярно обновляется и поддерживает современные технологии, сервис будет работать корректно.":{"en":"HarmonyAI works in all modern browsers that support current web standards. If your browser is updated regularly and supports modern technologies, the service will work correctly.","fr":"HarmonyAI fonctionne dans tous les navigateurs récents qui respectent les standards web actuels. Si votre navigateur est mis à jour régulièrement, le service fonctionnera correctement.","de":"HarmonyAI funktioniert in allen modernen Browsern, die aktuelle Webstandards unterstützen. Wird Ihr Browser regelmäßig aktualisiert, läuft der Dienst einwandfrei.","es":"HarmonyAI funciona en todos los navegadores modernos compatibles con los estándares web actuales. Si tu navegador se actualiza con regularidad, el servicio funcionará correctamente.","it":"HarmonyAI funziona in tutti i browser moderni che supportano gli standard web attuali. Se il tuo browser si aggiorna regolarmente, il servizio funzionerà correttamente.","zh":"HarmonyAI 可在所有支持现行网页标准的现代浏览器中使用。只要你的浏览器保持更新，服务就能正常运行。"},"Требуется ли мощное устройство?":{"en":"Do I need a powerful device?","fr":"Faut-il un appareil puissant ?","de":"Braucht man ein leistungsstarkes Gerät?","es":"¿Hace falta un dispositivo potente?","it":"Serve un dispositivo potente?","zh":"需要高性能设备吗？"},"Нет. Все вычисления происходят на серверах HarmonyAI, поэтому высокая производительность устройства не требуется. Даже на относительно слабых смартфонах и компьютерах сервис работает стабильно при наличии стабильного интернет-соединения.":{"en":"No. All the computing happens on HarmonyAI’s servers, so high device performance isn’t needed. Even on relatively weak phones and computers the service runs smoothly as long as the internet connection is stable.","fr":"Non. Tous les calculs se font sur les serveurs de HarmonyAI : un appareil performant n’est pas nécessaire. Même sur des smartphones et ordinateurs peu puissants, le service fonctionne bien avec une connexion Internet stable.","de":"Nein. Alle Berechnungen laufen auf den Servern von HarmonyAI, daher ist keine hohe Geräteleistung nötig. Selbst auf eher schwachen Smartphones und Computern läuft der Dienst bei stabiler Internetverbindung zuverlässig.","es":"No. Todos los cálculos se hacen en los servidores de HarmonyAI, así que no se necesita un dispositivo potente. Incluso en móviles y ordenadores modestos el servicio funciona bien con una conexión estable.","it":"No. Tutti i calcoli avvengono sui server di HarmonyAI, quindi non serve un dispositivo potente. Anche su smartphone e computer poco performanti il servizio funziona bene con una connessione stabile.","zh":"不需要。所有计算都在 HarmonyAI 的服务器上完成，对设备性能没有要求。即使是配置较低的手机和电脑，只要网络稳定也能流畅使用。"},"Как удалить аккаунт?":{"en":"How do I delete my account?","fr":"Comment supprimer mon compte ?","de":"Wie lösche ich mein Konto?","es":"¿Cómo elimino mi cuenta?","it":"Come elimino il mio account?","zh":"如何注销账户？"},"Если вы хотите полностью удалить свой аккаунт и связанные с ним данные, необходимо обратиться в службу поддержки. После обработки обращения аккаунт будет удален в соответствии с действующей Политикой конфиденциальности. Перед удалением рекомендуется убедиться, что вам больше не понадобится сохраненная история чатов.":{"en":"If you want to delete your account and all related data completely, contact support. Once your request is processed, the account will be deleted in accordance with the current Privacy Policy. Before deleting, make sure you no longer need your saved chat history.","fr":"Si vous souhaitez supprimer complètement votre compte et les données associées, contactez l’assistance. Après traitement de la demande, le compte sera supprimé conformément à la Politique de confidentialité en vigueur. Avant la suppression, assurez-vous de ne plus avoir besoin de l’historique de vos conversations.","de":"Möchten Sie Ihr Konto und alle zugehörigen Daten vollständig löschen, wenden Sie sich an den Support. Nach Bearbeitung der Anfrage wird das Konto gemäß der geltenden Datenschutzerklärung gelöscht. Prüfen Sie vorher, ob Sie den gespeicherten Chatverlauf noch brauchen.","es":"Si quieres eliminar por completo tu cuenta y los datos asociados, contacta con soporte. Una vez tramitada la solicitud, la cuenta se eliminará conforme a la Política de privacidad vigente. Antes de eliminarla, asegúrate de que ya no necesitas el historial de chats guardado.","it":"Se vuoi eliminare completamente l’account e i dati collegati, contatta l’assistenza. Dopo l’elaborazione della richiesta, l’account verrà eliminato secondo l’Informativa sulla privacy in vigore. Prima di eliminarlo, assicurati di non avere più bisogno della cronologia delle chat salvata.","zh":"如需彻底删除账户及相关数据，请联系客服。处理申请后，账户将按现行《隐私政策》删除。删除前请确认不再需要已保存的聊天记录。"},"Можно ли использовать один аккаунт на нескольких устройствах?":{"en":"Can I use one account on several devices?","fr":"Puis-je utiliser un même compte sur plusieurs appareils ?","de":"Kann ich ein Konto auf mehreren Geräten nutzen?","es":"¿Puedo usar una cuenta en varios dispositivos?","it":"Posso usare un account su più dispositivi?","zh":"一个账户可以在多台设备上使用吗？"},"Да. Один аккаунт можно использовать одновременно на нескольких устройствах. После входа по электронной почте вся история чатов, настройки и информация автоматически синхронизируются между устройствами, благодаря чему вы сможете продолжить работу с любого места.":{"en":"Yes. One account can be used on several devices at the same time. After you sign in with your email, all your chat history, settings and information are synced automatically between devices, so you can continue from anywhere.","fr":"Oui. Un même compte peut être utilisé simultanément sur plusieurs appareils. Après la connexion par e-mail, l’historique, les paramètres et les informations se synchronisent automatiquement, pour reprendre où que vous soyez.","de":"Ja. Ein Konto lässt sich gleichzeitig auf mehreren Geräten nutzen. Nach der Anmeldung per E-Mail werden Chatverlauf, Einstellungen und Daten automatisch zwischen den Geräten synchronisiert, sodass Sie überall weitermachen können.","es":"Sí. Una cuenta se puede usar a la vez en varios dispositivos. Tras iniciar sesión con el correo, el historial de chats, la configuración y los datos se sincronizan automáticamente entre dispositivos y puedes continuar desde cualquier lugar.","it":"Sì. Un account si può usare contemporaneamente su più dispositivi. Dopo l’accesso con l’email, cronologia delle chat, impostazioni e dati si sincronizzano automaticamente, così puoi continuare ovunque.","zh":"可以。一个账户可同时在多台设备上使用。用邮箱登录后，聊天记录、设置和信息会在设备间自动同步，随时随地都能继续使用。"},"Какие новые функции появятся в будущем?":{"en":"What new features will appear in the future?","fr":"Quelles nouvelles fonctions arriveront ?","de":"Welche neuen Funktionen kommen künftig?","es":"¿Qué funciones nuevas llegarán?","it":"Quali nuove funzioni arriveranno?","zh":"未来会推出哪些新功能？"},"HarmonyAI постоянно развивается. В будущих обновлениях планируется выпуск более красивого интерфейса, новых моделей искусственного интеллекта, значительно улучшенного распознавания музыки, расширенных возможностей анализа музыкальных произведений, новых инструментов для учеников музыкальных школ и множества других функций. Все обновления добавляются постепенно после тщательного тестирования.":{"en":"HarmonyAI is constantly evolving. Future updates will bring a more beautiful interface, new AI models, much better music recognition, extended analysis of musical works, new tools for music school students and many other features. All updates are added gradually after thorough testing.","fr":"HarmonyAI évolue en permanence. Les prochaines mises à jour apporteront une interface plus belle, de nouveaux modèles d’IA, une reconnaissance musicale nettement améliorée, une analyse plus poussée des œuvres, de nouveaux outils pour les élèves d’écoles de musique et bien d’autres fonctions. Les nouveautés sont ajoutées progressivement, après des tests approfondis.","de":"HarmonyAI entwickelt sich ständig weiter. Künftige Updates bringen eine schönere Oberfläche, neue KI-Modelle, deutlich bessere Musikerkennung, erweiterte Analyse von Musikwerken, neue Werkzeuge für Musikschüler und viele weitere Funktionen. Alle Updates kommen schrittweise nach gründlichen Tests.","es":"HarmonyAI evoluciona constantemente. Las próximas actualizaciones traerán una interfaz más bonita, nuevos modelos de IA, un reconocimiento musical mucho mejor, más posibilidades de análisis de obras, nuevas herramientas para estudiantes de música y muchas otras funciones. Todas las novedades se añaden poco a poco tras pruebas minuciosas.","it":"HarmonyAI è in continua evoluzione. I prossimi aggiornamenti porteranno un’interfaccia più bella, nuovi modelli di IA, un riconoscimento musicale molto migliorato, strumenti avanzati di analisi dei brani, nuovi strumenti per gli studenti delle scuole di musica e molte altre funzioni. Tutti gli aggiornamenti arrivano gradualmente dopo test accurati.","zh":"HarmonyAI 在不断发展。后续更新将带来更美观的界面、新的 AI 模型、大幅改进的音乐识别、更强的作品分析能力、面向音乐学校学生的新工具以及更多功能。所有更新都会在充分测试后逐步上线。"},"Как предложить новую функцию?":{"en":"How can I suggest a new feature?","fr":"Comment proposer une nouvelle fonction ?","de":"Wie schlage ich eine neue Funktion vor?","es":"¿Cómo propongo una función nueva?","it":"Come posso proporre una nuova funzione?","zh":"如何建议新功能？"},"Если у вас появилась идея, которая может сделать HarmonyAI лучше, вы можете написать в службу поддержки. Мы внимательно читаем предложения пользователей и регулярно добавляем наиболее востребованные функции в планы разработки. Именно благодаря обратной связи сервис становится удобнее для всех.":{"en":"If you have an idea that could make HarmonyAI better, write to support. We read users’ suggestions carefully and regularly add the most requested features to our development plans. Feedback is exactly what makes the service more convenient for everyone.","fr":"Si vous avez une idée pour améliorer HarmonyAI, écrivez à l’assistance. Nous lisons attentivement les suggestions et ajoutons régulièrement les fonctions les plus demandées à notre feuille de route. C’est grâce à vos retours que le service devient plus pratique pour tous.","de":"Haben Sie eine Idee, wie HarmonyAI besser werden kann, schreiben Sie dem Support. Wir lesen die Vorschläge aufmerksam und nehmen die gefragtesten Funktionen regelmäßig in die Planung auf. Gerade durch Feedback wird der Dienst für alle bequemer.","es":"Si tienes una idea que pueda mejorar HarmonyAI, escribe a soporte. Leemos con atención las propuestas de los usuarios y añadimos con regularidad las funciones más pedidas a los planes de desarrollo. Gracias a los comentarios el servicio se vuelve más cómodo para todos.","it":"Se hai un’idea per migliorare HarmonyAI, scrivi all’assistenza. Leggiamo con attenzione le proposte degli utenti e inseriamo regolarmente le funzioni più richieste nei piani di sviluppo. È proprio grazie al feedback che il servizio diventa più comodo per tutti.","zh":"如果你有让 HarmonyAI 变得更好的想法，欢迎联系客服。我们会认真阅读用户建议，并定期把最受欢迎的功能纳入开发计划。正是这些反馈让服务对每个人都更好用。"},"Где можно следить за обновлениями?":{"en":"Where can I follow updates?","fr":"Où suivre les nouveautés ?","de":"Wo kann ich Neuigkeiten verfolgen?","es":"¿Dónde puedo seguir las novedades?","it":"Dove posso seguire gli aggiornamenti?","zh":"在哪里关注更新？"},"В ближайшее время будет запущен официальный Telegram-канал HarmonyAI, где будут публиковаться новости проекта, информация о новых функциях, исправлениях ошибок и крупных обновлениях. Ссылка на канал появится после его открытия.":{"en":"An official HarmonyAI Telegram channel will launch soon, with project news, information on new features, bug fixes and major updates. The link will appear once the channel opens.","fr":"Une chaîne Telegram officielle de HarmonyAI sera bientôt lancée, avec les actualités du projet, les nouvelles fonctions, les corrections et les mises à jour importantes. Le lien sera publié à son ouverture.","de":"In Kürze startet ein offizieller Telegram-Kanal von HarmonyAI mit Projektneuigkeiten, Informationen zu neuen Funktionen, Fehlerbehebungen und großen Updates. Der Link erscheint nach dem Start des Kanals.","es":"Pronto se lanzará el canal oficial de HarmonyAI en Telegram, con noticias del proyecto, información sobre nuevas funciones, correcciones de errores y actualizaciones importantes. El enlace aparecerá cuando se abra.","it":"A breve verrà lanciato il canale Telegram ufficiale di HarmonyAI, con notizie sul progetto, informazioni sulle nuove funzioni, correzioni di errori e aggiornamenti importanti. Il link comparirà all’apertura del canale.","zh":"HarmonyAI 官方 Telegram 频道即将上线，届时将发布项目动态、新功能、错误修复和重大更新。频道开通后会公布链接。"},"Когда новые функции становятся доступны пользователям?":{"en":"When do new features become available to users?","fr":"Quand les nouvelles fonctions deviennent-elles disponibles ?","de":"Wann werden neue Funktionen für Nutzer verfügbar?","es":"¿Cuándo están disponibles las nuevas funciones?","it":"Quando le nuove funzioni diventano disponibili?","zh":"新功能何时向用户开放？"},"Перед публикацией каждая новая функция проходит внутреннее тестирование разработчиками и модераторами. Это позволяет убедиться в ее стабильной работе и избежать появления серьезных ошибок. После успешного завершения тестирования функция становится доступна всем пользователям без необходимости устанавливать обновления.":{"en":"Before release, every new feature goes through internal testing by developers and moderators. This makes sure it works reliably and avoids serious bugs. After testing is completed successfully, the feature becomes available to all users without installing any updates.","fr":"Avant sa publication, chaque nouvelle fonction passe par des tests internes menés par les développeurs et les modérateurs. Cela permet de s’assurer de sa stabilité et d’éviter les erreurs graves. Une fois les tests réussis, la fonction devient accessible à tous, sans mise à jour à installer.","de":"Vor der Veröffentlichung durchläuft jede neue Funktion interne Tests durch Entwickler und Moderatoren. So wird sichergestellt, dass sie stabil läuft und keine gravierenden Fehler enthält. Nach erfolgreichem Abschluss der Tests steht die Funktion allen Nutzern zur Verfügung, ohne dass Updates installiert werden müssen.","es":"Antes de publicarse, cada nueva función pasa por pruebas internas de desarrolladores y moderadores. Así nos aseguramos de que funciona de forma estable y evitamos errores graves. Cuando las pruebas terminan con éxito, la función queda disponible para todos sin instalar actualizaciones.","it":"Prima del rilascio, ogni nuova funzione viene testata internamente da sviluppatori e moderatori. Questo garantisce che funzioni in modo stabile ed evita errori gravi. Dopo il superamento dei test, la funzione diventa disponibile per tutti senza dover installare aggiornamenti.","zh":"每项新功能上线前都会经过开发者和管理员的内部测试，以确保运行稳定、避免严重错误。测试通过后，功能会直接向所有用户开放，无需安装任何更新。"},"Что делать, если HarmonyAI мне не понравился?":{"en":"What if I don’t like HarmonyAI?","fr":"Et si HarmonyAI ne me plaît pas ?","de":"Was tun, wenn mir HarmonyAI nicht gefällt?","es":"¿Y si HarmonyAI no me gusta?","it":"E se HarmonyAI non mi piace?","zh":"如果我不喜欢 HarmonyAI 怎么办？"},"Нам очень жаль, если сервис не оправдал ваших ожиданий. HarmonyAI находится в активной стадии развития, поэтому мы постоянно работаем над исправлением ошибок, повышением качества ответов и добавлением новых функций. Если вы расскажете, что именно вас не устроило, мы обязательно рассмотрим ваше предложение и постараемся сделать сервис лучше.":{"en":"We’re very sorry if the service didn’t meet your expectations. HarmonyAI is in active development, so we keep working on fixing errors, improving answers and adding new features. If you tell us what exactly didn’t suit you, we will definitely consider your suggestion and try to make the service better.","fr":"Nous sommes désolés si le service n’a pas répondu à vos attentes. HarmonyAI est en plein développement : nous travaillons sans cesse à corriger les erreurs, à améliorer les réponses et à ajouter de nouvelles fonctions. Si vous nous dites ce qui ne vous a pas convenu, nous étudierons votre suggestion et tâcherons d’améliorer le service.","de":"Es tut uns sehr leid, wenn der Dienst Ihre Erwartungen nicht erfüllt hat. HarmonyAI befindet sich in aktiver Entwicklung, daher arbeiten wir ständig an Fehlerbehebungen, besseren Antworten und neuen Funktionen. Wenn Sie uns sagen, was Ihnen nicht gefallen hat, prüfen wir Ihren Vorschlag auf jeden Fall und versuchen, den Dienst zu verbessern.","es":"Sentimos mucho que el servicio no haya cumplido tus expectativas. HarmonyAI está en pleno desarrollo, así que trabajamos sin parar en corregir errores, mejorar las respuestas y añadir funciones. Si nos cuentas qué no te convenció, estudiaremos tu propuesta e intentaremos mejorar el servicio.","it":"Ci dispiace molto se il servizio non ha soddisfatto le tue aspettative. HarmonyAI è in pieno sviluppo, quindi lavoriamo continuamente per correggere errori, migliorare le risposte e aggiungere nuove funzioni. Se ci dici cosa non ti ha convinto, valuteremo sicuramente la tua proposta e cercheremo di migliorare il servizio.","zh":"很抱歉本服务没有达到你的预期。HarmonyAI 正在积极开发中，我们一直在修复错误、提升回答质量并增加新功能。如果你告诉我们具体哪里不满意，我们一定会认真考虑你的建议，努力把服务做得更好。"},"Можно ли полностью доверять ответам HarmonyAI?":{"en":"Can I fully trust HarmonyAI’s answers?","fr":"Peut-on se fier entièrement aux réponses de HarmonyAI ?","de":"Kann ich den Antworten von HarmonyAI voll vertrauen?","es":"¿Puedo confiar plenamente en las respuestas de HarmonyAI?","it":"Ci si può fidare completamente delle risposte di HarmonyAI?","zh":"可以完全信任 HarmonyAI 的回答吗？"},"HarmonyAI является искусственным интеллектом и, как любой современный искусственный интеллект, иногда может допускать ошибки. Несмотря на специализированное обучение и большую базу знаний, мы рекомендуем перепроверять особенно важную информацию по официальным источникам, учебникам или консультироваться с преподавателем.":{"en":"HarmonyAI is an artificial intelligence and, like any modern AI, can sometimes make mistakes. Despite specialised training and a large knowledge base, we recommend double-checking especially important information against official sources or textbooks, or consulting a teacher.","fr":"HarmonyAI est une intelligence artificielle et, comme toute IA moderne, elle peut parfois se tromper. Malgré un entraînement spécialisé et une vaste base de connaissances, nous recommandons de vérifier les informations particulièrement importantes auprès de sources officielles, de manuels ou d’un professeur.","de":"HarmonyAI ist eine künstliche Intelligenz und kann, wie jede moderne KI, manchmal Fehler machen. Trotz spezialisierten Trainings und einer großen Wissensbasis empfehlen wir, besonders wichtige Informationen anhand offizieller Quellen oder Lehrbücher zu prüfen oder eine Lehrkraft zu fragen.","es":"HarmonyAI es una inteligencia artificial y, como cualquier IA moderna, a veces puede equivocarse. Pese a su entrenamiento especializado y su amplia base de conocimientos, recomendamos comprobar la información especialmente importante en fuentes oficiales o manuales, o consultar a un profesor.","it":"HarmonyAI è un’intelligenza artificiale e, come ogni IA moderna, a volte può sbagliare. Nonostante l’addestramento specialistico e un’ampia base di conoscenze, consigliamo di verificare le informazioni particolarmente importanti su fonti ufficiali o manuali, oppure di consultare un insegnante.","zh":"HarmonyAI 是人工智能，和其他现代 AI 一样有时也会出错。尽管经过专门训练并拥有庞大的知识库，我们仍建议你对特别重要的信息通过官方资料、教材核实，或咨询老师。"},"Есть ли возрастные ограничения для использования сервиса?":{"en":"Are there age restrictions for using the service?","fr":"Y a-t-il des restrictions d’âge pour utiliser le service ?","de":"Gibt es Altersbeschränkungen für die Nutzung des Dienstes?","es":"¿Hay restricciones de edad para usar el servicio?","it":"Ci sono limiti di età per usare il servizio?","zh":"使用本服务有年龄限制吗？"},"Самостоятельно использовать HarmonyAI рекомендуется с 18 лет. Пользователи младше 18 лет могут пользоваться сервисом только с разрешения родителей или законных представителей. Используя HarmonyAI, вы подтверждаете, что соблюдаете требования Пользовательского соглашения.":{"en":"Independent use of HarmonyAI is recommended from the age of 18. Users under 18 may use the service only with the permission of their parents or legal guardians. By using HarmonyAI, you confirm that you comply with the User Agreement.","fr":"L’utilisation autonome de HarmonyAI est recommandée à partir de 18 ans. Les utilisateurs de moins de 18 ans ne peuvent utiliser le service qu’avec l’autorisation de leurs parents ou représentants légaux. En utilisant HarmonyAI, vous confirmez respecter le Contrat d’utilisation.","de":"Die selbstständige Nutzung von HarmonyAI wird ab 18 Jahren empfohlen. Nutzer unter 18 Jahren dürfen den Dienst nur mit Erlaubnis der Eltern oder gesetzlichen Vertreter nutzen. Mit der Nutzung von HarmonyAI bestätigen Sie, dass Sie die Nutzungsvereinbarung einhalten.","es":"Se recomienda usar HarmonyAI de forma autónoma a partir de los 18 años. Los menores de 18 solo pueden usar el servicio con permiso de sus padres o representantes legales. Al usar HarmonyAI confirmas que cumples el Acuerdo de usuario.","it":"L’uso autonomo di HarmonyAI è consigliato dai 18 anni. Gli utenti minori di 18 anni possono usare il servizio solo con il permesso dei genitori o dei rappresentanti legali. Usando HarmonyAI confermi di rispettare l’Accordo d’uso.","zh":"建议年满 18 岁的用户独立使用 HarmonyAI。未满 18 岁的用户只能在父母或法定监护人许可下使用。使用 HarmonyAI 即表示你确认遵守《用户协议》。"},"Можно ли использовать HarmonyAI в коммерческих целях?":{"en":"Can HarmonyAI be used for commercial purposes?","fr":"Peut-on utiliser HarmonyAI à des fins commerciales ?","de":"Darf HarmonyAI kommerziell genutzt werden?","es":"¿Se puede usar HarmonyAI con fines comerciales?","it":"HarmonyAI si può usare a fini commerciali?","zh":"可以将 HarmonyAI 用于商业用途吗？"},"На данный момент HarmonyAI разработан исключительно как образовательный сервис для учеников музыкальных школ. Использование платформы в коммерческих целях или для предоставления платных образовательных услуг без согласования с администрацией сервиса не предусмотрено.":{"en":"At the moment HarmonyAI is designed solely as an educational service for music school students. Using the platform for commercial purposes or to provide paid educational services without the service administration’s approval is not permitted.","fr":"Pour l’instant, HarmonyAI est conçue uniquement comme un service éducatif pour les élèves d’écoles de musique. L’utilisation de la plateforme à des fins commerciales ou pour fournir des services éducatifs payants sans l’accord de l’administration du service n’est pas prévue.","de":"Derzeit ist HarmonyAI ausschließlich als Bildungsdienst für Musikschüler konzipiert. Eine kommerzielle Nutzung der Plattform oder ihre Verwendung für kostenpflichtige Bildungsangebote ohne Abstimmung mit der Verwaltung des Dienstes ist nicht vorgesehen.","es":"Por ahora, HarmonyAI está concebido exclusivamente como un servicio educativo para estudiantes de escuelas de música. No está previsto usar la plataforma con fines comerciales ni para prestar servicios educativos de pago sin la autorización de la administración del servicio.","it":"Al momento HarmonyAI è pensata esclusivamente come servizio educativo per gli studenti delle scuole di musica. L’uso della piattaforma a fini commerciali o per offrire servizi educativi a pagamento senza l’accordo dell’amministrazione del servizio non è previsto.","zh":"目前，HarmonyAI 仅作为面向音乐学校学生的教育服务开发。未经服务管理方同意，不得将平台用于商业目的或提供付费教育服务。"},"Есть ли API для разработчиков?":{"en":"Is there an API for developers?","fr":"Existe-t-il une API pour les développeurs ?","de":"Gibt es eine API für Entwickler?","es":"¿Hay una API para desarrolladores?","it":"Esiste un’API per sviluppatori?","zh":"有面向开发者的 API 吗？"},"Да. У HarmonyAI есть публичный API, совместимый с Anthropic Messages API: модели dynatos и adanatos, оплата по фактическому числу токенов с отдельного баланса API. Ключи, баланс и инструкции для Claude Code, Cursor, OpenCode и других клиентов — на странице harmonyai.ru/api.":{"en":"Yes. HarmonyAI has a public API compatible with the Anthropic Messages API: the dynatos and adanatos models, billed by the actual number of tokens from a separate API balance. Keys, balance and instructions for Claude Code, Cursor, OpenCode and other clients are on the harmonyai.ru/api page.","fr":"Oui. HarmonyAI dispose d’une API publique compatible avec l’Anthropic Messages API : modèles dynatos et adanatos, facturation au nombre réel de jetons sur un solde API séparé. Clés, solde et instructions pour Claude Code, Cursor, OpenCode et d’autres clients sur la page harmonyai.ru/api.","de":"Ja. HarmonyAI bietet eine öffentliche API, kompatibel mit der Anthropic Messages API: Modelle dynatos und adanatos, Abrechnung nach tatsächlicher Tokenzahl von einem separaten API-Guthaben. Schlüssel, Guthaben und Anleitungen für Claude Code, Cursor, OpenCode und andere Clients finden Sie auf harmonyai.ru/api.","es":"Sí. HarmonyAI tiene una API pública compatible con la Anthropic Messages API: modelos dynatos y adanatos, con cobro por el número real de tokens desde un saldo de API independiente. Las claves, el saldo y las instrucciones para Claude Code, Cursor, OpenCode y otros clientes están en harmonyai.ru/api.","it":"Sì. HarmonyAI ha un’API pubblica compatibile con l’Anthropic Messages API: modelli dynatos e adanatos, con addebito in base al numero effettivo di token da un saldo API separato. Chiavi, saldo e istruzioni per Claude Code, Cursor, OpenCode e altri client sono su harmonyai.ru/api.","zh":"有。HarmonyAI 提供兼容 Anthropic Messages API 的公开 API：模型为 dynatos 和 adanatos，按实际 token 数从独立的 API 余额中扣费。密钥、余额以及 Claude Code、Cursor、OpenCode 等客户端的接入说明见 harmonyai.ru/api 页面。"},"Как связаться со службой поддержки?":{"en":"How do I contact support?","fr":"Comment contacter l’assistance ?","de":"Wie erreiche ich den Support?","es":"¿Cómo contacto con soporte?","it":"Come contatto l’assistenza?","zh":"如何联系客服？"},"Связаться со службой поддержки можно по специальной ссылке, которая будет размещена в приложении и на официальном сайте HarmonyAI. При обращении рекомендуется подробно описать проблему и, при необходимости, приложить скриншоты или другие материалы, которые помогут быстрее разобраться в ситуации.":{"en":"You can contact support via a dedicated link that will be placed in the app and on the official HarmonyAI website. When contacting us, describe the problem in detail and, if necessary, attach screenshots or other materials that will help us understand the situation faster.","fr":"Vous pouvez contacter l’assistance via un lien dédié qui sera placé dans l’application et sur le site officiel de HarmonyAI. Décrivez le problème en détail et joignez si nécessaire des captures d’écran ou d’autres éléments qui nous aideront à comprendre plus vite.","de":"Den Support erreichen Sie über einen speziellen Link, der in der App und auf der offiziellen Website von HarmonyAI bereitgestellt wird. Beschreiben Sie das Problem ausführlich und fügen Sie bei Bedarf Screenshots oder andere Materialien bei, die uns helfen, die Situation schneller zu verstehen.","es":"Puedes contactar con soporte mediante un enlace específico que estará en la aplicación y en el sitio oficial de HarmonyAI. Describe el problema con detalle y, si hace falta, adjunta capturas u otros materiales que nos ayuden a entender antes la situación.","it":"Puoi contattare l’assistenza tramite un link dedicato che sarà disponibile nell’app e sul sito ufficiale di HarmonyAI. Descrivi il problema nel dettaglio e, se serve, allega screenshot o altro materiale che ci aiuti a capire più rapidamente la situazione.","zh":"可以通过 HarmonyAI 应用和官方网站上的专用链接联系客服。联系时请详细描述问题，必要时附上截图或其他有助于快速了解情况的材料。"},"Где можно ознакомиться с Политикой конфиденциальности?":{"en":"Where can I read the Privacy Policy?","fr":"Où consulter la Politique de confidentialité ?","de":"Wo finde ich die Datenschutzerklärung?","es":"¿Dónde puedo leer la Política de privacidad?","it":"Dove posso leggere l’Informativa sulla privacy?","zh":"在哪里查看隐私政策？"},"Политика конфиденциальности всегда доступна в настройках HarmonyAI. В ней подробно описано, какие данные собираются сервисом, каким образом они используются, как обеспечивается их защита и какие права имеют пользователи при работе с платформой.":{"en":"The Privacy Policy is always available in the HarmonyAI settings. It describes in detail what data the service collects, how it is used, how it is protected and what rights users have when working with the platform.","fr":"La Politique de confidentialité est toujours accessible dans les paramètres de HarmonyAI. Elle décrit en détail les données collectées, leur utilisation, leur protection et les droits des utilisateurs sur la plateforme.","de":"Die Datenschutzerklärung ist jederzeit in den Einstellungen von HarmonyAI verfügbar. Sie beschreibt ausführlich, welche Daten der Dienst erhebt, wie sie genutzt und geschützt werden und welche Rechte Nutzer haben.","es":"La Política de privacidad está siempre disponible en la configuración de HarmonyAI. En ella se detalla qué datos recopila el servicio, cómo se usan, cómo se protegen y qué derechos tienen los usuarios en la plataforma.","it":"L’Informativa sulla privacy è sempre disponibile nelle impostazioni di HarmonyAI. Descrive nel dettaglio quali dati raccoglie il servizio, come vengono usati, come sono protetti e quali diritti hanno gli utenti sulla piattaforma.","zh":"《隐私政策》可随时在 HarmonyAI 设置中查看，其中详细说明了服务收集哪些数据、如何使用和保护这些数据，以及用户在使用平台时享有的权利。"},"Почему HarmonyAI может отвечать дольше обычного?":{"en":"Why can HarmonyAI take longer than usual to answer?","fr":"Pourquoi HarmonyAI peut-elle mettre plus de temps que d’habitude à répondre ?","de":"Warum antwortet HarmonyAI manchmal langsamer als sonst?","es":"¿Por qué HarmonyAI puede tardar más de lo habitual en responder?","it":"Perché HarmonyAI a volte risponde più lentamente del solito?","zh":"为什么 HarmonyAI 有时回答得比平时慢？"},"Время генерации ответа зависит от сложности запроса, выбранной модели, текущей нагрузки на серверы и используемых функций. Простые вопросы обычно обрабатываются за несколько секунд, а сложные запросы, анализ документов, генерация изображений или распознавание музыки могут потребовать немного больше времени.":{"en":"Response time depends on the complexity of the request, the chosen model, current server load and the features used. Simple questions are usually processed in a few seconds, while complex requests, document analysis, image generation or music recognition may take a bit longer.","fr":"Le temps de réponse dépend de la complexité de la demande, du modèle choisi, de la charge actuelle des serveurs et des fonctions utilisées. Les questions simples sont généralement traitées en quelques secondes, tandis que les demandes complexes, l’analyse de documents, la génération d’images ou la reconnaissance musicale peuvent prendre un peu plus de temps.","de":"Die Antwortzeit hängt von der Komplexität der Anfrage, dem gewählten Modell, der aktuellen Serverauslastung und den genutzten Funktionen ab. Einfache Fragen werden meist in wenigen Sekunden beantwortet, komplexe Anfragen, Dokumentanalysen, Bilderzeugung oder Musikerkennung können etwas länger dauern.","es":"El tiempo de respuesta depende de la complejidad de la petición, el modelo elegido, la carga actual de los servidores y las funciones utilizadas. Las preguntas sencillas suelen procesarse en pocos segundos, mientras que las peticiones complejas, el análisis de documentos, la generación de imágenes o el reconocimiento musical pueden tardar algo más.","it":"Il tempo di risposta dipende dalla complessità della richiesta, dal modello scelto, dal carico attuale dei server e dalle funzioni usate. Le domande semplici vengono di solito elaborate in pochi secondi, mentre richieste complesse, analisi di documenti, generazione di immagini o riconoscimento musicale possono richiedere un po’ più di tempo.","zh":"回答所需时间取决于问题复杂度、所选模型、当前服务器负载和使用的功能。简单问题通常几秒内完成，而复杂请求、文档分析、图片生成或音乐识别可能需要更长时间。"},"Что делать, если сервис временно недоступен?":{"en":"What should I do if the service is temporarily unavailable?","fr":"Que faire si le service est temporairement indisponible ?","de":"Was tun, wenn der Dienst vorübergehend nicht erreichbar ist?","es":"¿Qué hago si el servicio no está disponible temporalmente?","it":"Cosa fare se il servizio è temporaneamente non disponibile?","zh":"服务暂时不可用怎么办？"},"Иногда HarmonyAI может быть временно недоступен из-за технического обслуживания, обновления серверов или высокой нагрузки. В большинстве случаев работа восстанавливается автоматически в течение короткого времени. Если проблема сохраняется длительное время, рекомендуем обратиться в службу поддержки.":{"en":"HarmonyAI may occasionally be temporarily unavailable due to maintenance, server updates or high load. In most cases it recovers automatically within a short time. If the problem persists for a long time, please contact support.","fr":"HarmonyAI peut parfois être temporairement indisponible en raison d’une maintenance, d’une mise à jour des serveurs ou d’une forte charge. Dans la plupart des cas, le service se rétablit automatiquement en peu de temps. Si le problème persiste, contactez l’assistance.","de":"HarmonyAI kann gelegentlich wegen Wartung, Server-Updates oder hoher Last vorübergehend nicht erreichbar sein. Meist läuft der Dienst nach kurzer Zeit automatisch wieder. Besteht das Problem länger, wenden Sie sich bitte an den Support.","es":"A veces HarmonyAI puede no estar disponible temporalmente por mantenimiento, actualización de servidores o mucha carga. En la mayoría de los casos se restablece solo en poco tiempo. Si el problema persiste, contacta con soporte.","it":"A volte HarmonyAI può essere temporaneamente non disponibile per manutenzione, aggiornamento dei server o carico elevato. Nella maggior parte dei casi il servizio torna attivo da solo in poco tempo. Se il problema persiste a lungo, contatta l’assistenza.","zh":"HarmonyAI 有时可能因维护、服务器更新或高负载而暂时不可用。大多数情况下，服务会在短时间内自动恢复。如果问题长时间存在，请联系客服。"},"Как часто обновляется HarmonyAi?":{"en":"How often is HarmonyAi updated?","fr":"À quelle fréquence HarmonyAi est-elle mise à jour ?","de":"Wie oft wird HarmonyAi aktualisiert?","es":"¿Con qué frecuencia se actualiza HarmonyAi?","it":"Quanto spesso viene aggiornata HarmonyAi?","zh":"HarmonyAi 多久更新一次？"},"HarmonyAI развивается постоянно. Исправления ошибок, улучшения моделей и новые функции публикуются регулярно после внутреннего тестирования. Мы стремимся делать сервис лучше с каждым обновлением, сохраняя стабильность и качество работы.":{"en":"HarmonyAI is constantly developing. Bug fixes, model improvements and new features are released regularly after internal testing. We strive to make the service better with every update while keeping it stable and reliable.","fr":"HarmonyAI évolue en permanence. Corrections, améliorations des modèles et nouvelles fonctions sont publiées régulièrement après des tests internes. Nous nous efforçons d’améliorer le service à chaque mise à jour tout en préservant sa stabilité et sa qualité.","de":"HarmonyAI wird ständig weiterentwickelt. Fehlerbehebungen, Modellverbesserungen und neue Funktionen erscheinen regelmäßig nach internen Tests. Wir wollen den Dienst mit jedem Update besser machen und dabei Stabilität und Qualität bewahren.","es":"HarmonyAI evoluciona constantemente. Las correcciones, las mejoras de los modelos y las nuevas funciones se publican con regularidad tras las pruebas internas. Intentamos mejorar el servicio con cada actualización sin perder estabilidad ni calidad.","it":"HarmonyAI è in continuo sviluppo. Correzioni, miglioramenti dei modelli e nuove funzioni vengono pubblicati regolarmente dopo i test interni. Cerchiamo di migliorare il servizio a ogni aggiornamento mantenendone stabilità e qualità.","zh":"HarmonyAI 一直在发展。错误修复、模型改进和新功能会在内部测试后定期发布。我们力求每次更新都让服务更好，同时保持稳定和品质。"},"Ничего не найдено":{"en":"Nothing found","fr":"Aucun résultat","de":"Nichts gefunden","es":"No se encontró nada","it":"Nessun risultato","zh":"未找到相关内容"},"Вернуться назад":{"en":"Go back","fr":"Revenir en arrière","de":"Zurück","es":"Volver atrás","it":"Torna indietro","zh":"返回上一页"},"Поиск статей...":{"en":"Search articles...","fr":"Rechercher des articles...","de":"Artikel suchen...","es":"Buscar artículos...","it":"Cerca articoli...","zh":"搜索文章..."}});
